window.POEM_DB=window.POEM_DB||{};POEM_DB["song_043"]={"n":"洪咨夔","dyn":"宋","poems":[{"t":"寿刘宰","f":"七言律诗","c":["制锦新城衣锦归，种桃遗爱满桃蹊。","恩波淮水流不尽，福力螺山高与齐。","天上已催班玉笋，日边行见月璇题。","欢声都是长生曲，薰作香云覆宝猊。"]},{"t":"乙酉岁暮有感 其一","f":"七言绝句","c":["罢参归趁日高眠，随意翻书不计编。","岁事从教催白发，春风元只在丹田。"]},{"t":"乙酉岁暮有感 其二","f":"七言绝句","c":["精神收召入腔来，水色山光面目开。","可惜行窝新失伴，雪晴未忍说寻梅。"]},{"t":"乙酉岁暮有感 其三","f":"七言绝句","c":["樽酒团栾里社情，眼中忽不见公荣。","祗应天体如鸡子，地下人间共月明。"]},{"t":"丁东泉","f":"七言绝句","c":["渴乌滴尽三更雨，铁凤敲寒六月风。","汤饼困来茶未熟，为师摇梦作丁东。"]},{"t":"丁谓 其二","f":"七言绝句","c":["钦若奖丁丁陷若，谓之厚演演挤丁。","势交利合皆如此，说与金陵老子听。"]},{"t":"九日","f":"七言绝句","c":["老无擘画笑柴桑，两眼惺惺菊自黄。","渠更笑人无菊把，拒霜相对过重阳。"]},{"t":"九月一日侍老人游洞霄宿超然馆闻钟","f":"七言绝句","c":["太一相过烛未销，朝元钟动郁罗萧。","身轻不怕琼台滑，蹴踏青霞上斗杓。"]},{"t":"九月十八日夜泊刘郎浦 其二","f":"七言绝句","c":["平生意气压曹瞒，却为夫人鬓作斑。","堂上横刀何足问，五兵只在画屏间。"]},{"t":"二花","f":"七言绝句","c":["粲粲金钱映玉簪，荣华能得几光阴。","季伦歌妓春申客，零落秋风没处寻。"]},{"t":"入少城","f":"七言绝句","c":["严城槌鼓暝阴催，剑栈归来第几回。","喘汗老兵迎马报，燕王宫里海棠开。"]},{"t":"十一月五日锁学士院","f":"七言绝句","c":["楼头禁鼓试初挝，催草江淮督使麻。","落纸一帘风雨疾，不知斜墨阵翻鸦。"]},{"t":"又和 其六","f":"七言绝句","c":["架上乱书儿自整，床头浊酒妇能谋。","只将翘足垂莲势，静对书窗课弈秋。"]},{"t":"又和 其二","f":"七言绝句","c":["往来鱼虎涧流浅，出没鼠狼庭草荒。","宅近市傍人不到，独迎西日上东墙。"]},{"t":"又和 其九","f":"七言绝句","c":["蟹正肥时秋色老，鸦争噪处夕阳残。","未须多进玻瓈椀，满树霜红正好看。"]},{"t":"又和 其一","f":"七言绝句","c":["青女笼晴试小春，门前沙路净无尘。","平洲水竹因依好，白鹭飞来不避人。"]},{"t":"又和 其四","f":"七言绝句","c":["尔雅虫鱼已熟知，更将埤雅访农师。","投糟赤蟹真无价，荐饼黄鸡正及时。"]},{"t":"又和 其三","f":"七言绝句","c":["柳亚溪桥几换条，鬓根添得雪飘萧。","清臞自信堪骑鹤，最喜无钱绊住腰。"]},{"t":"又和 其七","f":"七言绝句","c":["风里行云不自由，低眉重整玉搔头。","桃根纵有飞花渡，燕子宁无接翅楼。"]},{"t":"又和 其八","f":"七言绝句","c":["寒灯芳烬发春红，读到豳诗继匪风。","吾道有消还有长，欲将此意写丝桐。"]},{"t":"又和 其十","f":"七言绝句","c":["天时人事共流通，何用将冰语夏虫。","判为梅花多酿酒，春风里着蜜翁翁。"]},{"t":"又和 其五","f":"七言绝句","c":["终朝聒得耳神飞，东舍西邻尽贩机。","百样攀花无我分，惯将帘作后堂衣。"]},{"t":"万杉寺散珠亭酌观音泉","f":"七言绝句","c":["苍杉拱立万夫长，破衲素封千户侯。","昨夜金仙失璎珞，寒光满地不曾收。"]},{"t":"万景楼次韵 其四","f":"七言绝句","c":["木落川空亦大奇，坐中亡酒客须追。","非渠江汉孟东野，孤我南山韩退之。"]},{"t":"万景楼次韵 其一","f":"七言绝句","c":["扶疏岩桂拒霜开，苍莽鵁鶄属玉来。","想见山阴秋色里，一声欸乃暮潮回。"]},{"t":"万景楼次韵 其五","f":"七言绝句","c":["霜碛萧萧落涨痕，西风吹日堕金盆。","冯高送目河湟外，万里戎情属柳浑。"]},{"t":"万景楼次韵 其六","f":"七言绝句","c":["过雁声中岁月侵，东流江水识归心。","峨眉天目高相似，多买青山尚及今。"]},{"t":"万景楼次韵 其三","f":"七言绝句","c":["秋入徐熙水墨山，荻花吹雪渺江干。","楼头未用催行酒，待到三更月上看。"]},{"t":"万景楼次韵 其二","f":"七言绝句","c":["金谷白头谁石友，香山青眼几殷兄。","三峨九顶知人意，长与江楼酒面平。"]},{"t":"三月十四日送焘东下至龙爪滩过虞开国坟庵见壁间虞仲易观棋诗有天上人间元一气如何顷刻烂樵柯之句雁湖甚赏之因用韵反骚","f":"七言绝句","c":["周天日月何曾住，大地山河祗自磨。","不死者存人独耳，会令斧亦烂如柯。"]},{"t":"下元节后省试进奏院吏","f":"七言绝句","c":["推云不动雨声苦，酝雪未成风力乾。","瘖鹜一庭淘墨汁，也烦老子坐深寒。"]},{"t":"千竿夹","f":"五言绝句","c":["方雨江流红，未霜芦花紫。","寂寂远帆来，拍拍晴鸥起。"]},{"t":"口占","f":"七言绝句","c":["秋风已飒梧犹碧，宿雨才收稗亦花。","天着工夫供醉眼，东邻有酒不堪赊。"]},{"t":"口占酬俞端叔牡丹","f":"七言绝句","c":["沉香亭北梦魂赊，惊见祥云七宝车。","穷孟尝君空好客，病维摩老不禁花。"]},{"t":"小雪前三日钟冠之约余侍老人行山舟发后洪入杜坞自郑盖庵过阆山趋翔凤山菁山遍览杨坟秀园遂至何山道场山乘兴薄吴兴访玉湖书院水晶境界而归自戊子至庚子阴晴相半胜处辄徘徊赋诗饮酒伟哉观也数诗见后 长桥渡","f":"七言绝句","c":["溪流转处两三家，落落疏林浅浅沙。","可是小春风物早，檐头一束杜鹃花。"]},{"t":"小雪前三日钟冠之约余侍老人行山舟发后洪入杜坞自郑盖庵过阆山趋翔凤山菁山遍览杨坟秀园遂至何山道场山乘兴薄吴兴访玉湖书院水晶境界而归自戊子至庚子阴晴相半胜处辄徘徊赋诗饮酒伟哉观也数诗见后 何山书堂","f":"七言绝句","c":["日高裹饭看何山，山缺东南水绕关。","松桧不摇风自度，读书声在白云间。"]},{"t":"小雪前三日钟冠之约余侍老人行山舟发后洪入杜坞自郑盖庵过阆山趋翔凤山菁山遍览杨坟秀园遂至何山道场山乘兴薄吴兴访玉湖书院水晶境界而归自戊子至庚子阴晴相半胜处辄徘徊赋诗饮酒伟哉观也数诗见后 阆山妙严院松月堂读张汪二公诗有感用无垢韵","f":"五言绝句","c":["止水搅不动，好山邀辄来。","松间寒月晚，似欠两翁催。"]},{"t":"小雪前三日钟冠之约余侍老人行山舟发后洪入杜坞自郑盖庵过阆山趋翔凤山菁山遍览杨坟秀园遂至何山道场山乘兴薄吴兴访玉湖书院水晶境界而归自戊子至庚子阴晴相半胜处辄徘徊赋诗饮酒伟哉观也数诗见后 其一 宿妙胜阁","f":"七言绝句","c":["钩辀格磔鸟呼晚，勃窣媻姗人试寒。","野水不流山四合，宝华云里着栏干。"]},{"t":"小雪前三日钟冠之约余侍老人行山舟发后洪入杜坞自郑盖庵过阆山趋翔凤山菁山遍览杨坟秀园遂至何山道场山乘兴薄吴兴访玉湖书院水晶境界而归自戊子至庚子阴晴相半胜处辄徘徊赋诗饮酒伟哉观也数诗见后 其二 宿妙胜阁","f":"七言绝句","c":["一径白云明似雪，满山红叶艳于花。","过溪买酒等闲事，只恐客来非当家。"]},{"t":"小雪前三日钟冠之约余侍老人行山舟发后洪入杜坞自郑盖庵过阆山趋翔凤山菁山遍览杨坟秀园遂至何山道场山乘兴薄吴兴访玉湖书院水晶境界而归自戊子至庚子阴晴相半胜处辄徘徊赋诗饮酒伟哉观也数诗见后 其一 宿资福小阁次梁间韵","f":"七言绝句","c":["古木阴阴兀老苍，月于疏处弄昏黄。","巡檐不见梅花面，认得东风句子香。"]},{"t":"小雪前三日钟冠之约余侍老人行山舟发后洪入杜坞自郑盖庵过阆山趋翔凤山菁山遍览杨坟秀园遂至何山道场山乘兴薄吴兴访玉湖书院水晶境界而归自戊子至庚子阴晴相半胜处辄徘徊赋诗饮酒伟哉观也数诗见后 其二 宿资福小阁次梁间韵","f":"七言绝句","c":["小窗无欠亦无馀，一榻翛然雪透肤。","收拾故书藏恰好，怕人写入凤山图。"]},{"t":"为清隐打化僧说偈","f":"七言绝句","c":["云山幸不求吾是，鱼鸟依然笑我顽。","自欲入城持钵去，扣门可煞老僧闲。"]},{"t":"五月庚申梦人相指为马周且诵诗两句觉而足之","f":"五言绝句","c":["伸缩一双手，去来三世身。","新丰惊昨梦，斗酒满怀春。"]},{"t":"元夕","f":"七言绝句","c":["轻阴不隔团团月，遗俗犹传缓缓歌。","踏雪看灯知不恶，宜春酿酒恨无多。"]},{"t":"六月十六日宣锁","f":"七言绝句","c":["禁门深钥寂无哗，浓墨淋漓两相麻。","唱彻五更天未晓，一池月浸紫薇花。"]},{"t":"六月六日宿观音寺次朝南韵 其二","f":"七言绝句","c":["煮饼无奚徒自苦，护篝有妾未为非。","为言示病维摩室，也解天花散乱飞。"]},{"t":"六月六日宿观音寺次朝南韵 其一","f":"七言绝句","c":["微管仲其左衽矣，舍安石如苍生何。","须君快草三秦檄，尽为先生祛宿痾。"]},{"t":"天池灯","f":"七言绝句","c":["山谷人家避李成，谁知劫数莫逃兵。","到今鬼燐青无数，认作文殊佛火明。"]},{"t":"月下用郑大参和沾维那圆觉韵","f":"七言绝句","c":["无缝冰轮万古同，御风飞到碧天中。","四方上下无遮碍，一点清光处处通。"]},{"t":"水仙兰","f":"七言绝句","c":["水仙潇洒伴梅寒，鸿雁行中合数兰。","七里香花陪隶耳，涪翁醉眼被粗瞒。"]},{"t":"水牡丹","f":"七言绝句","c":["魏紫潜绯真正红，天公不管老东风。","紫袍玉带双鱼挂，犹把阑珊造化功。"]},{"t":"王章","f":"七言绝句","c":["皂囊盥手自封题，忘却牛衣忍冻啼。","一点丹心通碧落，岁寒宁负白头妻。"]},{"t":"东山塔影","f":"七言绝句","c":["相轮高插碧霄寒，好是如如不动山。","弄影翻光颠倒转，微权只在隙窗间。"]},{"t":"东西山 其二","f":"七言绝句","c":["折屐棋边情易矫，捋须筝畔泪难禁。","何如拍手招元放，玉室金堂深更深。"]},{"t":"东西山 其一","f":"七言绝句","c":["西山许迈无人问，只说东山有谢安。","富贵光明贫贱晦，世情从古两般看。"]},{"t":"包港风涛 其二","f":"七言绝句","c":["颠风立海雷轰柁，骇浪翻天雪压篷。","夜半乖龙酣战退，一奁冰鉴本来空。"]},{"t":"包港风涛 其一","f":"七言绝句","c":["䉲百丈几牵掣断，铁三脚已撼摇浮。","阳侯戏剧何须尔，身世从来等一沤。"]},{"t":"发阆州 其二","f":"七言绝句","c":["木奴夭矫二十里，大似盘龙趋桂林。","中人薄暑遽如许，觅树依凉无好阴。"]},{"t":"句 其一","f":"七言绝句","c":["拓罢淮南金戟牙，时平来坐野僧家。","枪旗谩摘社前雨，旌节旋移春后花。"]},{"t":"四月壬午发利州 其一","f":"七言绝句","c":["十里迎春水面开，橹声不动柁声催。","春山转处疑江尽，白鸟迎人曲折来。"]},{"t":"四月壬午发利州 其二","f":"七言绝句","c":["两岸骚骚麦尾黄，茅檐半瓦荫垂杨。","牧儿吹笛随归犊，浅草平沙暝色苍。"]},{"t":"对门 其一","f":"七言绝句","c":["对门三日罢晨炊，无处佣身老画师。","安得化山为饭颗，大家鼓腹太平时。"]},{"t":"对门 其二","f":"七言绝句","c":["一帘霏雨暗花朝，焙药炉边拥破貂。","深坐不知畦麦信，喜看黄液上瓶焦。"]},{"t":"归宗墨池","f":"七言绝句","c":["龙跳虎跃入昭陵，墨汁空留一段冰。","散作淋漓元气湿，屋头老木挂疏藤。"]},{"t":"正月十九日孟享从驾 其一","f":"七言绝句","c":["黄伞中间一点红，绣云卤簿海棠风。","钧容声出云霄外，马上谁怜有老聋。"]},{"t":"用胡卫道赠姚居士韵","f":"七言绝句","c":["牢落淮南赋小山，霜风容易老人颜。","扬澜左蠡天垂碧，梦与盟鸥共往还。"]},{"t":"用钟侍郎韵赠懒谷","f":"七言绝句","c":["蒲团竹几妙高台，瞑坐何能放眼开。","门外白云多事在，又将飞雨出山来。"]},{"t":"田家以二月二日晴雨占谷价枕上口占","f":"七言绝句","c":["葛根已尽麦方青，延颈东来米价平。","怕听三更三点雨，要占二月二朝晴。"]},{"t":"白羊同行五六登无尽墓入义方传庆寺读钟离公所书两句赠八琼张子高碑及吕公来访事程教有诗次其韵 其二","f":"七言绝句","c":["墓前苍干直能奇，勾引先生读断碑。","见说嘉禾曾有颂，平生行止不须疑。"]},{"t":"白鹤观","f":"七言绝句","c":["缺唇丹井应千尺，秃顶灵杉恰百围。","鹤去不闻人下子，黄蜂无数采花归。"]},{"t":"礼灭翁退天台能仁院归梁渚一绝寄之","f":"七言绝句","c":["倒劄枯藤立晚风，山光不与水俱东。","蘋花落尽芦花老，地阔天高一个鸿。"]},{"t":"仲冬九日还可庵谒墓遂入都","f":"七言绝句","c":["未放梅梢一个春，枇杷花已玉嶙峋。","霜靴带取苔痕去，应被孤猿野鹤嗔。"]},{"t":"仲冬二日还自谷川道中 其一","f":"七言绝句","c":["晴烟杳霭似春山，疏柳啼鸦意度闲。","溪上麦田翻未遍，故迟牛带夕阳还。"]},{"t":"仲冬二日还自谷川道中 其二","f":"七言绝句","c":["满天返照醉红殷，未到生明月已弯。","好是蛾眉无点恨，盈盈淡扫有无间。"]},{"t":"刘后溪和雁湖即事诗十绝见示次韵 其八","f":"七言绝句","c":["雪花白尽沔山头，咽咽冰澌沔水流。","不见将军阚如虎，行人犹指定功楼。"]},{"t":"刘后溪和雁湖即事诗十绝见示次韵 其七","f":"七言绝句","c":["桔柏津头访昔游，夕阳衰草几番秋。","人心谁向忙中觉，天理须从定处求。"]},{"t":"刘后溪和雁湖即事诗十绝见示次韵 其四","f":"七言绝句","c":["去年灶妇饱而腴，今岁啼饥眼欲枯。","麦饭熟时犹远在，不多元气急须扶。"]},{"t":"刘后溪和雁湖即事诗十绝见示次韵 其九","f":"七言绝句","c":["槿花朝发夕而萎，得失兴亡总一机。","古往今来磨不尽，人间公是与公非。"]},{"t":"刘后溪和雁湖即事诗十绝见示次韵 其二","f":"七言绝句","c":["断烟落日护林丘，三数人家屋打头。","见说春来寒更甚，补窗塞户胜防秋。"]},{"t":"刘后溪和雁湖即事诗十绝见示次韵 其一","f":"七言绝句","c":["谁家柳系夜郎舟，半月风颠估客愁。","起候五更风脚定，安排篙楫放中流。"]},{"t":"刘后溪和雁湖即事诗十绝见示次韵 其五","f":"七言绝句","c":["夔人壁栅未曾修，好事痴儿只浪游。","草树低迷风淅沥，于菟又在屋山头。"]},{"t":"刘后溪和雁湖即事诗十绝见示次韵 其六","f":"七言绝句","c":["金谷人家大谬悠，春江自理送穷舟。","渔人拍手从旁笑，淡饭粗衣过即休。"]},{"t":"刘后溪和雁湖即事诗十绝见示次韵 其三","f":"词","c":["巴山深处一江流，好着藏书百尺楼。","椳?栌栌浑易得，杏梁桂柱若为求。"]},{"t":"刘后溪和雁湖即事诗十绝见示次韵 其十","f":"七言绝句","c":["中原离合数由天，百战关河血满川。","日月赤云占胜气，挂弓何处是祁连。"]},{"t":"同日次韵可庵","f":"七言绝句","c":["梦破巫峰十二鬟，家山逸驾尚容攀。","桃花见面东风里，应笑陈人老上颜。"]},{"t":"同孙子直和李参政东园韵 其六","f":"七言绝句","c":["食肉玉关徒自苦，然脐郿坞太生痴。","人心溪壑元无底，富贵功名十二时。"]},{"t":"同孙子直和李参政东园韵 其八","f":"七言绝句","c":["大渡画河馀玉斧，祁山破贼只纶巾。","圣贤深意谁能会，满径桃梅又着人。"]},{"t":"同孙子直和李参政东园韵 其五","f":"七言绝句","c":["办得萧萧水竹居，闭门足了一生娱。","坐忘老子慵开眼，强聒痴儿任挽须。"]},{"t":"同孙子直和李参政东园韵 其九","f":"七言绝句","c":["孔明遁世吟梁甫，范蠡遭时策计然。","钟鼎山林非二物，莫随穷达较蚩妍。"]},{"t":"同孙子直和李参政东园韵 其四","f":"七言绝句","c":["狂蝶正便春从臾，好花犹怯冷禁持。","从渠歌彻铁如意，输我兴来金屈卮。"]},{"t":"同孙子直和李参政东园韵 其三","f":"七言绝句","c":["破舰已风方汹汹，积薪未火又悠悠。","天公解管人间事，甲子占晴稳有秋。"]},{"t":"同孙子直和李参政东园韵 其七","f":"七言绝句","c":["院落深沉燕子归，应时纳祜试春衣。","海棠过雨精神索，杨柳无风力气微。"]},{"t":"同孙子直和李参政东园韵 其二","f":"七言绝句","c":["治国宜将治圃看，垦除容易整齐难。","沼泉莫放源头浊，种竹先教地步宽。"]},{"t":"同孙子直和李参政东园韵 其十","f":"七言绝句","c":["露下三更月满林，鹤眠未警独长吟。","芭蕉身世都来几，天地中间要立心。"]},{"t":"岁晏 其一","f":"七言绝句","c":["得路只轮车易上，失时独幅被难眠。","淡黄齑饭茅柴酒，东掩西遮也过年。"]},{"t":"岁晏 其二","f":"七言绝句","c":["百想卧轮翻伎俩，三生圆泽弄精魂。","何如静对梅花坐，春满江南雪后村。"]},{"t":"次及甫入峡杂咏 其一 三游洞","f":"七言绝句","c":["寥阳殿古琼关启，祇树园深宝盖张。","长啸一声空响答，只疑惊起橘中商。"]},{"t":"次及甫入峡杂咏 其二 三游洞","f":"七言绝句","c":["披苔觅字双明健，倚树商诗两鬓皤。","地划天开今几世，往来人物尽消磨。"]},{"t":"次及甫入峡杂咏 平善坝","f":"七言绝句","c":["水风静处抛船易，山雨晴时着句难。","便向个中占好谶，一程平善过云安。"]},{"t":"次及甫入峡杂咏 至喜亭","f":"七言绝句","c":["巴峡头边第一州，竹枝歌里水东流。","盖亭老柳今如此，六一先生几系舟。"]},{"t":"次及甫入峡杂咏 钓鱼石翁","f":"七言绝句","c":["刀耕火种皆丘甲，背负腰缠尽算缗。","独有石翁鱼得计，至今疑是避秦人。"]},{"t":"次及甫入峡杂咏 虾蟆培泉","f":"七言绝句","c":["丹墀万字中兴策，西蜀人材待细抡。","好把玉蜍留水去，直言莫问近前嗔。"]},{"t":"次张义立登九顶三绝 其一 大像","f":"七言绝句","c":["坐断江山现法身，大光明里万波旬。","东风归棹津头过，同是慈航得度人。"]},{"t":"次张义立登九顶三绝 其三 乌尤","f":"七言绝句","c":["酒壮千林如欲舞，诗豪万景不容骄。","山中肯着如斯客，来听春风婆饼焦。"]},{"t":"次李参政晚春湖上口占十绝 其七","f":"七言绝句","c":["近山气候易凉温，云为阴晴半吐吞。","草木趋新千万态，芸芸何者是归根。"]},{"t":"次李参政晚春湖上口占十绝 其九","f":"七言绝句","c":["燕子将雏鹿养茸，年华冉冉鬓成翁。","拂开万古瞢腾眼，多少英豪老彀中。"]},{"t":"次李参政晚春湖上口占十绝 其二","f":"七言绝句","c":["藉地残花五色茵，东风来去寂无痕。","馀香不肯污尘土，留得蜂房活计温。"]},{"t":"次李参政晚春湖上口占十绝 其一","f":"七言绝句","c":["缡褷瘦鹤耻乘轩，踏遍莓苔十亩园。","欲下横塘还决去，涨痕一尺晚来浑。"]},{"t":"次李参政晚春湖上口占十绝 其八","f":"七言绝句","c":["绿阴羃定蔚蓝天，庭户萧然有漏仙。","麦饭熟时蚕百箔，山中啼鸟识丰年。"]},{"t":"次李参政晚春湖上口占十绝 其五","f":"七言绝句","c":["屋角春声几样翻，勾牵春梦绕丘樊。","三桃二李成阴早，恨不安仁老灌园。"]},{"t":"次李参政晚春湖上口占十绝 其十","f":"七言绝句","c":["潼关杀气渺春阴，渭水泱泱柳色深。","为问草庐人起否，汉家遗老尚讴吟。"]},{"t":"次李参政晚春湖上口占十绝 其四","f":"七言绝句","c":["雨过桃花尽处源，庭前新绿长芳荪。","目前点检燕支篆，手汲清泉洗着樽。"]},{"t":"次李阆州禀议三首 其二 立春日风","f":"七言绝句","c":["千骑行春雪未消，早乘羊角问逍遥。","明年好与供春帖，淑景祥飙近九霄。"]},{"t":"次李阆州禀议三首 其一 训狐","f":"七言绝句","c":["顽民迁洛风随改，佞士归唐操立更。","勿怪训狐知气转，铜丸落落便春声。"]},{"t":"次李阆州禀议三首 其三 益昌","f":"七言绝句","c":["长恨诗人挽不来，东风无赖又帆开。","城南城北佳山水，多少甘棠手自栽。"]},{"t":"次赵保之清明即事 其一","f":"七言绝句","c":["饼吃红绫空复忆，钱分白打底曾知。","推排风雨清明过，只有梨花三两枝。"]},{"t":"次赵保之清明即事 其二","f":"七言绝句","c":["草草携家去踏青，旧阡新冢纸钱轻。","触怀易作中年恶，羡杀儿童笑语声。"]},{"t":"次赵保之清明即事 其四","f":"七言绝句","c":["看花何必只长安，到处韶华总一般。","可是家贫风物晚，郎当莴笋斗春盘。"]},{"t":"次赵保之清明即事 其三","f":"七言绝句","c":["花信东风第几回，萧条门巷老苍苔。","汉宫尽有新钻火，无分传将一点来。"]},{"t":"次虞宪日近即事 其二","f":"七言绝句","c":["丙中甲上奇章石，水底山巅杜预碑。","矻矻一生图不朽，光风好处几曾知。"]},{"t":"次虞宪日近即事 其四","f":"七言绝句","c":["急雨萧萧撼瓦沟，梦随潮落浙江头。","倚门白发迟归信，不为莼丝烂熳秋。"]},{"t":"次虞宪日近即事 其一","f":"七言绝句","c":["风落虚檐燕子声，屋头屋尾菜花明。","炉熏燕坐参消息，理本无亏莫望盈。"]},{"t":"次虞宪日近即事 其三","f":"七言绝句","c":["衾寒更着痴儿踏，背痒时令丑妇搔。","骨肉团栾穷亦好，谁能膏火自煎熬。"]},{"t":"次虞宪日近即事 其五","f":"七言绝句","c":["梅桃结子绿阴浓，饶与葵榴自在红。","只有道根须猛进，未甘四下二之中。"]},{"t":"次韵张提刑送行 其二","f":"七言绝句","c":["伊川去后几多年，道在离堆沫水边。","身任兹文须着力，莫将人事属之天。"]},{"t":"次韵张提刑送行 其四","f":"七言绝句","c":["太白尝嗟蜀道艰，少陵欲铲剑门山。","何如推起蓬窗看，万里江天碧鸟还。"]},{"t":"次韵张提刑送行 其六","f":"七言绝句","c":["云边江树作离声，回首秋光满渭城。","蜀水吴山无间断，只应明月识人情。"]},{"t":"次韵张提刑送行 其五","f":"七言绝句","c":["了无薏苡可囊珠，解事家人气甚都。","日试西川煎茗法，半投白垩半鸡苏。"]},{"t":"次韵闵饥 其二","f":"七言绝句","c":["巷头巷尾几夷齐，日为饥肠不肯西。","只愿天公多雨粟，便教米价贱如泥。"]},{"t":"次韵闵饥 其一","f":"七言绝句","c":["贵人生长不知田，丝竹声中醉饱眠。","渠信春山青草尽，排门三日未炊烟。"]},{"t":"次韵娑罗花","f":"七言绝句","c":["摩耶树老无多子，天女花妍有许般。","莫把东边枝便斫，堂堂留与碧霄干。"]},{"t":"次韵荼蘼 其一","f":"七言绝句","c":["璎珞垂垂萼绿华，光明淡伫自成家。","枕帏酝藉风流足，甘放朝来被底衙。"]},{"t":"次韵荼蘼 其二","f":"七言绝句","c":["爱春留得琼英在，添竹扶将翠蔓高。","更着金沙相间种，主人四壁锦周遭。"]},{"t":"次韵游龙门十绝 其八","f":"七言绝句","c":["不提长剑斩江蛟，便揭脩竿钓海鳌。","纵老无成犹自许，一溪流水两山桃。"]},{"t":"次韵游龙门十绝 其七","f":"七言绝句","c":["稻花秋晚蟹洗手，荠菜春初饧胶牙。","筑底空山谁办此，留君只有石边茶。"]},{"t":"次韵游龙门十绝 其二","f":"七言绝句","c":["欲访天池水发源，倒骑北斗挟飞仙。","高低八节滩头路，俛仰三生石上缘。"]},{"t":"次韵游龙门十绝 其十","f":"七言绝句","c":["平明出去日斜回，小立岩花涧草隈。","光景留连非我事，此心曾点漆雕开。"]},{"t":"次韵游龙门十绝 其九","f":"七言绝句","c":["不知我者谓何哉，布袜青鞋日日催。","长啸一声啼鸟外，朵颐有象著山雷。"]},{"t":"次韵游龙门十绝 其五","f":"七言绝句","c":["武陵溪上迷津处，衡岳峰头失道时。","珍重牧儿相指似，隔林招手不吾欺。"]},{"t":"次韵游龙门十绝 其三","f":"七言绝句","c":["拍手东风唤白猿，划开元盖洞天门。","可能路指虚无去，两脚须留点地跟。"]},{"t":"次韵游龙门十绝 其六","f":"七言绝句","c":["飞泉溅雪林华湿，盘石生云古藓乾。","早著些词招隐去，泰山有贼脍人肝。"]},{"t":"次韵游龙门十绝 其一","f":"七言绝句","c":["若木扶桑莫苦攀，芙蓉薜荔不妨闲。","封三万户烟云里，化百千身水石间。"]},{"t":"江头寄致远 其二","f":"七言绝句","c":["客窗翻遍竹炉香，楼外更声作许长。","解事灯花相报似，拥炉儿女说荒唐。"]},{"t":"江头寄致远 其一","f":"七言绝句","c":["箕斗光移析木津，踏霜扶醉不惊尘。","夜寒应是梅花觉，半敛愁容婉待春。"]},{"t":"灯夕独酌 其一","f":"七言绝句","c":["钿车罗帕禁街夜，珂伞炬城沙路春。","少不自强今老矣，落梅风暖酒生鳞。"]},{"t":"灯夕独酌 其二","f":"七言绝句","c":["海涛风定柳枝曲，江楫波明桃叶歌。","剪烛停杯听宛转，不妨白雪映青蛾。"]},{"t":"至日欢喜口号 其一","f":"七言绝句","c":["太平宝庆第三年，万乘初郊大报天。","恰应汉家辛巳日，八觚泰畤立甘泉。"]},{"t":"至日欢喜口号 其二","f":"七言绝句","c":["青城矗矗紫坛深，碧宇无风挂斗参。","亿万苍生齐合爪，圣明天子得天心。"]},{"t":"至节出谒回 其二","f":"七言绝句","c":["巧笑声摇六博盆，纤纤人在绿窗根。","隔纱想见春风面，云滑金钗欲溜痕。"]},{"t":"至节出谒回 其一","f":"七言绝句","c":["一脉阳从地底回，人情物意便春台。","鲜衣稚子面红醉，知向外家参节来。"]},{"t":"西庵晚步","f":"七言绝句","c":["荷披菰折似秋严，茀草丛中菊露尖。","只有木犀荒不得，媻跚勃窣上亭檐。"]},{"t":"过三鹤山 其一","f":"七言绝句","c":["造物工夫拙剪裁，群芳各自得春开。","梨花嫁与东风去，随后荼蘼作媵来。"]},{"t":"严陵道上杂咏 其七","f":"七言绝句","c":["细草护沙连不断，疏风略雨散还收。","山田麦熟不归去，三百里江都是愁。"]},{"t":"严陵道上杂咏 其六","f":"七言绝句","c":["高高下下客行路，整整斜斜人住家。","端的今年蚕较晚，石榴花下响缫车。"]},{"t":"严陵道上杂咏 其五","f":"七言绝句","c":["闯巢抟黍待晨饷，投岸舂锄寻暮栖。","总是心为形所役，搔头独立渡桥西。"]},{"t":"严陵道上杂咏 其四","f":"七言绝句","c":["石坛千尺薜萝古，沙径百盘苔藓香。","不是先生求矫世，懒将日月趁人忙。"]},{"t":"严陵道上杂咏 其三","f":"七言绝句","c":["玄英范老闻风起，俱为羊裘一钓丝。","堂扁三贤非本意，何如只号子陵祠。"]},{"t":"严陵道上杂咏 其二","f":"七言绝句","c":["半江云湿欲成雨，两岸水浑初退潮。","短短竹篱花朵压，深深麦坞雉媒娇。"]},{"t":"严陵道上杂咏 其一","f":"七言绝句","c":["江上送行潮汛小，船头回首夕阳多。","人生有几柳如此，客思不禁花柰何。"]},{"t":"初霜","f":"五言绝句","c":["庭下晓来霜，菰顿芭蕉折。","络石瘦菖蒲，独抱青青节。"]},{"t":"寿崔帅卿 其七","f":"七言绝句","c":["垂弧节过便春风，入侍猩袍一点红。","殿上兽樽谁得饮，汉廷诸老定输公。"]},{"t":"寿崔帅卿 其四","f":"七言绝句","c":["弄兵澒洞射阳秋，一纸招呼杀气收。","十万苍生惊魄定，活人阴德过宾州。"]},{"t":"寿崔帅卿 其六","f":"七言绝句","c":["纷纷传檄方言战，猝猝囊金又说和。","谁信规摹须早定，计然半策不须多。"]},{"t":"寿崔帅卿 其二","f":"七言绝句","c":["连蜷雌霓堕晴空，光照书楼卷纸红。","天为斯文开瑞应，海南海北一宗工。"]},{"t":"寿崔帅卿 其五","f":"七言绝句","c":["夕烽旁午彻甘泉，独有淮东一臂全。","若使尽从持重计，庙谟底用更忧边。"]},{"t":"寿崔帅卿 其三","f":"七言绝句","c":["塞下人家盎盎春，又推馀泽及流民。","庆州小范青州富，合作先生社稷身。"]},{"t":"寿崔帅卿 其一","f":"七言绝句","c":["岭右山川间出贤，开元宰相最居先。","中间不数余安道，恰到于今五百年。"]},{"t":"怀程及甫 其二","f":"七言绝句","c":["石马门前万里回，向人似亦笑颜开。","独寻旧日题诗处，却恨骚翁不共来。"]},{"t":"怀程及甫 其一","f":"七言绝句","c":["撇濆梢涡稳下舟，狼牙鹿角又黄牛。","儿曹脱险欢呶甚，数到家山十二州。"]},{"t":"杨汉州见和答之 其二","f":"七言绝句","c":["春随落絮去堂堂，白发相看作许长。","人物如公犹未节，诸生何敢薄淮阳。"]},{"t":"杨汉州见和答之 其一","f":"七言绝句","c":["西楼伴食老西堂，拆袜浑无半线长。","推向万山深处去，沉犀桥北望龙阳。"]},{"t":"杨花","f":"七言绝句","c":["旧雨人无半迹来，惺惺独坐眼慵开。","却嫌飞絮犹多事，点破门前一径苔。"]},{"t":"里人送芍药用韵","f":"七言绝句","c":["诗墨淋漓似小王，殷勤包赠暖红香。","扬州金系腰何在，随分留春共一觞。"]},{"t":"闰月廿六日奉御香祈天竺观音于昭庆寺是日得霁","f":"七言绝句","c":["大士慈悲出补陀，扫除阴翳作人和。","武康芋子盐官枣，遇着丰年也倍多。"]},{"t":"阻风呈赵史君 其三","f":"七言绝句","c":["迟速乘除转晚飙，布帆快意定明朝。","庐山试问高多少，欲望西川万里桥。"]},{"t":"阻风呈赵史君 其二","f":"七言绝句","c":["倚风晴缆着烟莎，一抹斜阳白鸟过。","脱手簿书无半点，细翻黄卷课龟罗。"]},{"t":"阻风呈赵史君 其一","f":"七言绝句","c":["长红送酒出江城，樯燕喃喃第二程。","风色似知攀卧意，打头未肯放船行。"]},{"t":"取凉 其一","f":"七言绝句","c":["六月冷官还解热，解衣盘礴坐苍苔。","微风只在松梢顶，着意招呼不下来。"]},{"t":"取凉 其二","f":"七言绝句","c":["平湖水则减三分，尚欠红蕖一段云。","万斛波光自吞吐，月明亦足张吾军。"]},{"t":"和子有感时","f":"七言绝句","c":["八州都督新推毂，两纪中书旧覆瓯。","郿坞然脐如有策，聊城飞笴便无忧。"]},{"t":"和俞成大八月梅花","f":"七言绝句","c":["秋光深处送春来，青叶扶疏数点梅。","料是知君新酿熟，搀先九月菊花开。"]},{"t":"和续古蜜朮","f":"七言绝句","c":["参桂齐名骨自香，百花酿醑助甘凉。","含金咀玉风标别，消得肩吾为发扬。"]},{"t":"和黄几叔墨梅 其二","f":"七言绝句","c":["六月夜窗留取看，霜风萧飒堕林端。","问渠底事青青晚，耻上寻常桃李盘。"]},{"t":"和黄几叔墨梅 其一","f":"七言绝句","c":["月暗云迷竹外枝，寒香未动便能奇。","面如坡老南归后，骨似温公独乐时。"]},{"t":"和黄宰招饮","f":"七言绝句","c":["大都春色三分耳，能得眉头几度开。","见说东家酒初熟，不论今雨也须来。"]},{"t":"和楼前梅 其一","f":"七言绝句","c":["飞香涨艳拍檐牙，暖热楼居鄂陆家。","宝髻盘鸦冰柱晓，倚阑平折北梢花。"]},{"t":"和楼前梅 其二","f":"七言绝句","c":["楼高夜静月华陈，冷浸含章一段春。","人影花光相上下，定知梅亦解分身。"]},{"t":"庚寅元日甲子晴","f":"七言绝句","c":["圣君元命是元正，三素云开甲子晴。","不识姓名农圃老，相逢便与贺升平。"]},{"t":"弥牟观土八阵寄程嘉定","f":"七言绝句","c":["房公堂是盖公堂，漏下无声日正长。","应念常山蛇阵处，有人搔首立斜阳。"]},{"t":"抹利","f":"七言绝句","c":["翡翠帘帷雪透肌，纤风不动闹香吹。","裴回顾影精神发，省得京华识面时。"]},{"t":"林氏著存亭","f":"七言绝句","c":["有铭于鼎未为著，无忝所生方是存。","筱下若人元不死，春风吹雨着寒根。"]},{"t":"林同年被檄来体访民租寓僧舍有诗因次韵 其二","f":"七言绝句","c":["我虽不饱尚二簋，人则何辜无一襦。","官侬早下减租笔，天下可肥身宁臞。"]},{"t":"直玉堂和李参政绝句","f":"七言绝句","c":["曲折宫墙日影方，堂深人静似山梁。","斲榈叶底梅花老，次第风光到海棠。"]},{"t":"试院口占 其一","f":"七言绝句","c":["燕随社去雁初来，黄蜀葵花隔岸开。","万里江湖秋思动，捣橙和蟹荐新醅。"]},{"t":"试院口占 其二","f":"七言绝句","c":["追怀三五少年时，岁月堂堂两鬓丝。","茅屋秋风归未决，障泥能费几熊皮。"]},{"t":"雨中次韵 其一","f":"七言绝句","c":["积多云鹤岩前雨，种遍长松墓上田。","丰歉相乘天有数，今年管取斗三钱。"]},{"t":"青玉峡","f":"七言绝句","c":["水绕江南阿李家，满空飞雪响雷车。","流将采石矶头去，坐看浮梁压浪花。"]},{"t":"青草梦诗后两句早作足之","f":"七言绝句","c":["乾马坤牛放手骑，纵横上下尽通逵。","杖头挑起东风海，挂向东边若木枝。"]},{"t":"青渠追和宋金部壁间韵 其二","f":"七言绝句","c":["汗青孰与老黄间，能为君王把蜀山。","懊恼秋风吹客鬓，一年三过剑门关。"]},{"t":"青渠追和宋金部壁间韵 其一","f":"七言绝句","c":["短亭放脚小轩渠，从险趋平本一涂。","掌上烟川三百里，蜀都风物似吴都。"]},{"t":"促织 其一","f":"七言绝句","c":["一点光分草际萤，缲车未了纬车鸣。","催科知要先期办，风露饥肠织到明。"]},{"t":"促织 其二","f":"七言绝句","c":["水碧衫裙透骨鲜，飘摇机杼夜凉边。","隔林恐有人闻得，报县来拘土产钱。"]},{"t":"俞成大送新芋","f":"七言绝句","c":["谢三郎女败蓑衣，褴缕中藏玉雪肌。","柱下莫愁无乳媪，秋风得此可忘饥。"]},{"t":"奖菊 其一","f":"七言绝句","c":["木犀满送第三香，交割秋光与后行。","细雨斜风篱下菊，安排青蕊做重阳。"]},{"t":"奖菊 其二","f":"七言绝句","c":["菰叶离披藕叶攲，精神得似未秋时。","西风坐断群芳路，不属黄花更属谁。"]},{"t":"峡中","f":"七言绝句","c":["清猿遗响落三巴，树老霜迟叶未霞。","大抵近南春易早，梅花开尽又桃花。"]},{"t":"幽芳晚凉倚窗观稼 其一","f":"七言绝句","c":["晚风不动稻苗平，叶叶头边沆瀣明。","井养不穷功用在，谁将易象细推评。"]},{"t":"春日山行 其二","f":"七言绝句","c":["两点眼光牛背上，一窝春色落花边。","世缘不到山深处，只恐深山起世缘。"]},{"t":"春日山行 其一","f":"七言绝句","c":["一晴一雨柳添碧，半落半开梅著酸。","不被东风相鼓弄，春山只有老苍官。"]},{"t":"春行","f":"七言绝句","c":["野荼蘼发牡丹开，蔌蔌杨花堕酒杯。","过尽韶华才一出，祗应唤作探春来。"]},{"t":"春思 其一","f":"七言绝句","c":["柳汁何能染鬓根，柳丝只解绊愁魂。","年光有底催人急，水牡丹花又上盆。"]},{"t":"春思 其二","f":"七言绝句","c":["细草荒烟古墓田，知经寒食几年天。","雪条花下翩翩纸，疑是曾分白打钱。"]},{"t":"春思 其三","f":"七言绝句","c":["蝴蝶深深浅浅黄，被春恼得一般狂。","打团飞入菜花去，自信世间无别香。"]},{"t":"柳絮 其一","f":"七言绝句","c":["造化勿忘还勿助，精神非色亦非空。","残云初雪雍容甚，高下东风点乱红。"]},{"t":"柳絮 其二","f":"七言绝句","c":["风标清白难谐俗，气候中和易得朋。","招不肯来麾不去，若无才思渠应能。"]},{"t":"独夜","f":"七言绝句","c":["两窗明月一庭霜，佛屋风铃语夜长。","孤酌不多人易醒，九回肠付篆盘香。"]},{"t":"秋半闻莺","f":"七言绝句","c":["木叶青黄几栗留，尽情啼破两山幽。","怕人冷落生秋思，故作春声为遣愁。"]},{"t":"秋思","f":"五言绝句","c":["一曲玉连琐，十分金屈卮。","故新相代谢，底用为秋悲。"]},{"t":"荆州江浮水灯作佛事","f":"七言绝句","c":["谁把银河彻底倾，倒翻星斗著行明。","又疑笼道红栀子，隐隐鸣鞘出五更。"]},{"t":"草堂","f":"七言绝句","c":["严武能诗甫亦诗，诗名相轧便相疑。","思量世上交游事，大似诗名更可知。"]},{"t":"送范漕赴召 其三","f":"七言绝句","c":["急符唤出雅州丁，刀染红巾血雨腥。","定蜀论功谁第一，茗山合着后溪铭。"]},{"t":"送范漕赴召 其八","f":"七言绝句","c":["红丝步障海棠开，底似西湖半树梅。","要试平生调鼎手，安排青子待公来。"]},{"t":"送范漕赴召 其二","f":"七言绝句","c":["淮头蜀口几虺隤，百战山川入眼来。","行伍姓名浑历历，定知水镜不遗材。"]},{"t":"送范漕赴召 其四","f":"七言绝句","c":["走卒儿童口是碑，百年几见好监司。","浣花镜月经行处，草木江山亦去思。"]},{"t":"送范漕赴召 其六","f":"七言绝句","c":["匹马西征岁月多，苍头引鹤共婆娑。","传闻虚伫如清献，益漕归来径上坡。"]},{"t":"送范漕赴召 其七","f":"词","c":["天道频年说好还，到今胡?没天山。","延英为奏平戎策，只在人心国势间。"]},{"t":"送商总郎 其三","f":"七言绝句","c":["百寻浮玉三更月，万里长江一色秋。","照映此心须此水，不妨小泊读书舟。"]},{"t":"送商总郎 其二","f":"七言绝句","c":["霜迟断陇荞花白，水足平田稻子红。","剩把丰年供祖帐，送将玉节过江东。"]},{"t":"送商总郎 其一","f":"七言绝句","c":["鹤唳风声淝水捷，马腾士饱蔡州平。","笑谈定取中兴策，莫道司存只饷兵。"]},{"t":"首夏一绝示徐锦囊","f":"七言绝句","c":["金丸未熟樱桃过，锦幄俱空芍药来。","共坐晚凉观物化，床头有酒为君开。"]},{"t":"凉月 其二","f":"七言绝句","c":["金粟安排雨后黄，定知花亦爱新凉。","夜深月透玲珑影，花自光明月自香。"]},{"t":"凉月 其一","f":"七言绝句","c":["莲房折尽只留荷，露盖班班一丈过。","高下横斜无定影，聚凉着得月明多。"]},{"t":"夏至过东市 其一","f":"七言绝句","c":["插遍秧畴雨恰晴，牧儿顶踵是升平。","秃穿犊鼻迎风去，横坐牛腰趁草行。"]},{"t":"夏至过东市 其二","f":"七言绝句","c":["涨落平溪水见沙，绿阴两岸市人家。","晚风来去吹香远，蔌蔌冬青几树花。"]},{"t":"病起独步","f":"七言绝句","c":["病将春到眼慵开，只为梅花猛一来。","何处琵琶推却手，举头啄木起林隈。"]},{"t":"益昌次费伯矩赠行韵 其五","f":"七言绝句","c":["快须涤砚入承明，烂熳飞章拂太清。","富贵功名元素定，莫随人后颂升平。"]},{"t":"益昌次费伯矩赠行韵 其四","f":"七言绝句","c":["幕下精神清似水，门前责望重于山。","君家文伟规摹在，事业全归静定间。"]},{"t":"益昌次费伯矩赠行韵 其三","f":"七言绝句","c":["朝气风生暮气归，将材零落事功微。","酸风斜谷祁山路，眼底何人插羽飞。"]},{"t":"益昌次费伯矩赠行韵 其二","f":"七言绝句","c":["掎角中原二百州，熟知彼己是良筹。","时贤所及都能几，清渭黄河祗自流。"]},{"t":"益昌次费伯矩赠行韵 其一","f":"七言绝句","c":["浯水欲磨元结颂，聊城未下鲁连书。","静中好与高抬眼，恐有英豪在草庐。"]},{"t":"笋蕨","f":"七言绝句","c":["小儿握固骨何弱，稚子着绷肌尚寒。","岂不爱渠风味好，只应催我鬓毛残。"]},{"t":"绣观音酬郢州王知录丹青美人之赠两绝 其二","f":"七言绝句","c":["十相端严具足身，一团杨柳净瓶春。","石城莫与蛾眉看，羞不如人却妒人。"]},{"t":"绣观音酬郢州王知录丹青美人之赠两绝 其一","f":"七言绝句","c":["楚人不识女须面，只画昭君并莫愁。","赢得江南穷相眼，自嗟空白一生头。"]},{"t":"读史 其一","f":"七言绝句","c":["泗水飞沉周宝鼎，霸城遏住汉铜人。","人心不似无情物，多少英豪入魏秦。"]},{"t":"读史 其三","f":"七言绝句","c":["黄门常侍祷明堂，窦武陈蕃横被殃。","料得天公方睡着，不应受嘱变官方。"]},{"t":"读史 其二","f":"七言绝句","c":["晋将屈乘饵来虞，越送西施买断吴。","马齿虽高人未老，五湖风月䄠陶朱。"]},{"t":"读楞严","f":"七言绝句","c":["人人有路證无还，一念才差隔万山。","识得吾儒无妄卦，筏城长语尽须删。"]},{"t":"陪郡侯出郊劝农 其二","f":"七言绝句","c":["山青未了晓光开，鸠唤鸠应雨又催。","消得犊车泥滑滑，此行不为杏花来。"]},{"t":"陪郡侯出郊劝农 其五","f":"七言绝句","c":["炼丹人去屋萧萧，脚底群山走翠蛟。","长啸一声空响答，砉然只鹤起松梢。"]},{"t":"陪郡侯出郊劝农 其一","f":"七言绝句","c":["劝农冠盖出江干，马上东风觱栗寒。","珍重春衫唾花碧，画眉狼籍道傍看。"]},{"t":"陪郡侯出郊劝农 其四","f":"七言绝句","c":["争问官侬子谓谁，看来似不是农师。","向人羞道闲陪涉，说与豳风七月诗。"]},{"t":"陪郡侯出郊劝农 其三","f":"七言绝句","c":["茅屋人家蓐食烟，相呼趁雨好翻田。","去年下麦泥如铁，一寸春膏直几钱。"]},{"t":"陪郡侯出郊劝农 其六","f":"七言绝句","c":["半落梅花雪透明，不妨把酒当春行。","光风有意相料理，杨柳青边约略晴。"]},{"t":"寄题成都张宰压云楼 其一","f":"七言绝句","c":["清霜戒晓日将出，急雨报晴云乍开。","庭下簿书浑引却，独揩双眼上楼来。"]},{"t":"寄题成都张宰压云楼 其二","f":"七言绝句","c":["气如轲也生于义，道似参乎任以仁。","乾盖坤舆犹塞破，何难压倒玉嶙峋。"]},{"t":"庾楼","f":"七言绝句","c":["湓城陶庾共功名，庙食楼居孰重轻。","衮衮长江流不尽，淮山青处夕阳明。"]},{"t":"晚食","f":"七言绝句","c":["从来此腹负将军，淡饭投齑现报身。","三月不曾知笋蕨，梦魂敢到水晶鳞。"]},{"t":"晚凉","f":"七言绝句","c":["樛枝阴合翠熏笼，曲曲斜斜石径通。","窈眇蝉声缲独茧，为渠立尽晚来风。"]},{"t":"梅 其二","f":"七言绝句","c":["繁芳玉立夹胡床，勾引春韶午梦长。","有眼尽迷空里色，无心方识定中香。"]},{"t":"梅 其三","f":"七言绝句","c":["竹屋茅檐一树斜，冰霜意气盖韶华。","有馀不尽如知道，半已青青半尚花。"]},{"t":"梅 其四","f":"七言绝句","c":["桃花红艳照银床，黄入金明柳线长。","欲与晚梅相辈行，同时到底不同香。"]},{"t":"梅 其一","f":"七言绝句","c":["寒瓶虚插一枝斜，留待春风放霁华。","已信不冰方着水，可怜欲槁更开花。"]},{"t":"梅 其二","f":"七言绝句","c":["苍枝老去藓痕乾，唤起东风点暮寒。","会得生生无尽意，雪花零乱月栏干。"]},{"t":"梅 其一","f":"七言绝句","c":["风霜摇落都卢尽，一点春回造化家。","万物成终又成始，须将艮体看梅花。"]},{"t":"梅 其一","f":"七言绝句","c":["玉佩琼裾萼绿华，铜瓶清浸广寒家。","客怀无着春风处，醉向梢头嚼尽花。"]},{"t":"梅 其二","f":"七言绝句","c":["寒根不与物俱陈，髁髁梢头寂寂春。","却月凌风谁会得，不沾一叶是真身。"]},{"t":"清明 其二","f":"七言绝句","c":["风将好梦到兰亭，惊觉虚檐九子铃。","老眼醒来无着处，倚楼检校树头青。"]},{"t":"清明 其一","f":"七言绝句","c":["梨花匼匝不见叶，柳穟玲珑初欲绵。","寒食清明等闲过，日长翻覆压书眠。"]},{"t":"清凉院僧房致斋","f":"五言绝句","c":["花片墙阴晚，禽声屋角晴。","东风犹峭在，煨芋坐深明。"]},{"t":"续梦","f":"七言绝句","c":["琉璃庭扣水晶栏，宝树婆娑玉斧闲。","只恐姮娥嫌冷落，却随飞月下人间。"]},{"t":"铨闱董试上巳二绝 其一","f":"七言绝句","c":["天气年年只么新，官忙不似旧闲身。","油车画舫西湖闹，可惜埋头典却春。"]},{"t":"雪叹 其一","f":"七言绝句","c":["唐时三月十八雪，况复今年多一旬。","万紫千红浑过尽，荼蘼满架与争春。"]},{"t":"雪叹 其二","f":"七言绝句","c":["桑颖骚骚麦又萎，雪花如椀雨如丝。","老天只解苦黔首，快活贵人那得知。"]},{"t":"喜雨一绝简赵丞","f":"七言绝句","c":["龙公有眼识英材，好雨随声唤得来。","酒面添如田水满，眉头放与稻花开。"]},{"t":"寒暄不齐 其二","f":"七言绝句","c":["次第新烟欲试茶，铮铮飞霰响檐牙。","惜春苦欲春长在，且得轻寒约住花。"]},{"t":"寒暄不齐 其一","f":"七言绝句","c":["社后归来燕两三，门前细柳绿掺掺。","乞将蝴蝶蜻蜓扇，与试鹅黄水碧衫。"]},{"t":"敞云楼 其一","f":"七言绝句","c":["江天云作黑山颓，上到楼头手决开。","水墨枕屏三百里，斜阳属玉一双来。"]},{"t":"敞云楼 其二","f":"七言绝句","c":["草树成行整复斜，江头白处定芦花。","夜深更着无边月，好个楼居处士家。"]},{"t":"普照僧生云轩云闲阁 其一","f":"五言绝句","c":["岩芳敛空华，谷响答虚牝。","坐看白云生，会得无生忍。"]},{"t":"暑坐","f":"七言绝句","c":["隔帘草树隔溪山，密密深深洞启关。","水色山光无障碍，南风送入乱书间。"]},{"t":"朝南以诗送巴石研屏香几用韵 其二 研屏","f":"七言绝句","c":["首鼠年来困两端，石屏空照鬓丝斑。","归舟莫道全无物，分得蓬婆小雪山。"]},{"t":"朝南以诗送巴石研屏香几用韵 其二 香几","f":"七言绝句","c":["竹风吹酒未全醒，梦入香炉五老云。","好句得君青玉案，起来盥手炷清熏。"]},{"t":"朝南以诗送巴石研屏香几用韵 其一 香几","f":"七言绝句","c":["玉版横陈醉眼边，尚馀金鸭水沉烟。","客窗寂寂那消得，祗有南丰一瓣缘。"]},{"t":"温泉院 其二","f":"七言绝句","c":["神虎护泉寒翠壁，灵虬吐沫暖冰壶。","玉环不碎征尘里，更引三郎到古渝。"]},{"t":"温泉院 其一","f":"七言绝句","c":["老火欺人客路长，舣舟取次浴温汤。","犬鸣三峡夜逾静，月上四更天始凉。"]},{"t":"答子有","f":"七言绝句","c":["裹饭无人过子桑，拒霜一径雨昏黄。","花根记缚西湖缆，红浅红深醉夕阳。"]},{"t":"答吴叔永叔长 其一","f":"七言绝句","c":["刮霜面目澹无华，落落孤山处士家。","若使世间蜂蝶觉，光风纵好不成花。"]},{"t":"答吴叔永叔长 其二","f":"七言绝句","c":["瓶笙吹彻砚蜍乾，独有梅花伴夜寒。","万境空明香一点，世尘元自不相干。"]},{"t":"答家朝南 其二","f":"七言绝句","c":["角声悽惋笛声乾，独立黄昏不柰寒。","未省半山梅在否，东风归路忆长干。"]},{"t":"答家朝南 其一","f":"七言绝句","c":["竹光水色近宣华，彷佛江南万里家。","可是老谙春寂寞，夜深无梦到梅花。"]},{"t":"答高才卿 其一","f":"七言绝句","c":["烟波只艇着吾徒，莼鲙秋风早忆吴。","左蟹右杯东计决，醉来万事付含糊。"]},{"t":"答高才卿 其二","f":"七言绝句","c":["脆胜芎苗软胜脂，雅宜碧椀贮流离。","渠渠地主恩何在，骨里黄金祗自知。"]},{"t":"答程教见和梅诗 其二","f":"七言绝句","c":["春阴欲雪冻云乾，索笑疏枝共一寒。","静里闻香祗自觉，怕人饶舌似丰干。"]},{"t":"答程教见和梅诗 其一","f":"七言绝句","c":["一段清冰浸月华，短篱疏竹是谁家。","春光元不分吴蜀，惊见江南半树花。"]},{"t":"答程嘉定 其二","f":"七言绝句","c":["铃索闲闲静冶堂，槐阴匼匝柳丝长。","东君五日如京兆，早及残红醉艳阳。"]},{"t":"答程嘉定 其一","f":"七言绝句","c":["练袂蒿簪不下堂，肯随时世画眉长。","旁人莫解东风意，只道花梢合向阳。"]},{"t":"臈中步月 其二","f":"七言绝句","c":["卖妻鬻子年饥后，索母求爷贼乱馀。","对月椎胸几家哭，更堪萧索岁将除。"]},{"t":"臈中步月 其一","f":"七言绝句","c":["平山堂下解围去，天水堡前经战来。","天地无情一般月，照人霜骨白皑皑。"]},{"t":"幕官相约观芳草于法曹之亭黄宰病不至以诗来因次韵","f":"七言绝句","c":["似无细雨还应有，欲落馀花更复留。","草际水边青未了，可禁杯酒为扶头。"]},{"t":"新月","f":"五言绝句","c":["天面如人面，昏昏镇是愁。","晚来云色解，新月放眉头。"]},{"t":"楚城靖节祠","f":"楚辞体","c":["雨引莓苔上短垣，流泉无恙自涓涓。","不如归去来兮好，百世闻风只杜鹃。"]},{"t":"楞伽山房 其一","f":"七言绝句","c":["八万猊床方丈室，九千书卷半边窗。","儋翁句子无人问，流水泠泠度石矼。"]},{"t":"谨和老人初冬寓笔十绝 其二","f":"七言绝句","c":["是非不验道应坏，祸福无凭天也荒。","便使曹瞒生卖履，已赊王衍死排墙。"]},{"t":"谨和老人初冬寓笔十绝 其六","f":"七言绝句","c":["避风台上深情宠，偃月堂中尽意谋。","争柰天公无面目，满林黄叶一番秋。"]},{"t":"谨和老人初冬寓笔十绝 其五","f":"七言绝句","c":["两仪亦有盈亏数，万物难逃出入机。","一把牙筹空自苦，盖棺着得几通衣。"]},{"t":"谨和老人初冬寓笔十绝 其一","f":"七言绝句","c":["平泉草木须臾梦，金谷莺花一撮尘。","富贵若生根到底，两家占断别无人。"]},{"t":"谨和老人初冬寓笔十绝 其八","f":"七言绝句","c":["元子扫空桓氏业，窟郎荡尽李家风。","前人留得儿孙立，何患鸾枝不长桐。"]},{"t":"谨和老人初冬寓笔十绝 其三","f":"七言绝句","c":["何人地下管天条，不是皋陶即是萧。","金埒谩誇钱过斗，铁围宁问玉垂腰。"]},{"t":"谨和老人初冬寓笔十绝 其十","f":"七言绝句","c":["命有穷通分虎鼠，事无得失尽鸡虫。","东篱独有黄花在，挹取寒香寿阿翁。"]},{"t":"谨和老人初冬寓笔十绝 其九","f":"七言绝句","c":["方穷蔡泽问唐举，未遇邺侯逢懒残。","触石起云能沛雨，不应长作旱雷看。"]},{"t":"谨和老人初冬寓笔十绝 其四","f":"七言绝句","c":["当场弄出百般奇，傀儡棚中老偃师。","满眼机关无着处，到头线索有收时。"]},{"t":"谨和老人莲桂 其一","f":"七言绝句","c":["点破秋光数叶荷，水清时见小鱼过。","渟涵风露三更足，收拾江湖万顷多。"]},{"t":"谨和老人莲桂 其二","f":"七言绝句","c":["捣成一百八丸黄，入手能令热恼凉。","金粟如来身已化，蕊珠仙子骨犹香。"]},{"t":"路逢徽州送牡丹入都","f":"七言绝句","c":["飞絮游丝弄霁华，出门芳草渺天涯。","太平莫道全无象，脱绣鸣铃传送花。"]},{"t":"嘉陵江舟中 其二","f":"七言绝句","c":["辛夷零落水生漪，睡暖沙凫荫酒旗。","不是归帆相料理，春光如许底能知。"]},{"t":"嘉陵江舟中 其一","f":"七言绝句","c":["柳色黄黄草色微，一川新渌两红衣。","老天也信还家好，淡日柔风送客归。"]},{"t":"嘉陵江舟中 其三","f":"七言绝句","c":["东风吹老地棠花，燕子归来认得家。","茅屋石田浑好在，白头何苦尚天涯。"]},{"t":"端平二年端午帖子词 其五 皇帝閤","f":"七言绝句","c":["登进英才追庆历，开延正论踵咸平。","朝廷有道长如此，拜赐宫衣信是荣。"]},{"t":"端平二年端午帖子词 其三 皇帝閤","f":"五言绝句","c":["明进离方午，柔生遇已阴。","妙参三圣易，细测两仪心。"]},{"t":"端平二年端午帖子词 其四 皇帝閤","f":"七言绝句","c":["缉熙虚敞薰飔细，清燕深明昼晷长。","大学中庸翻咏久，金猊几度手添香。"]},{"t":"端平二年端午帖子词 其二 皇帝閤","f":"五言绝句","c":["雨足秧分圳，风清麦弄岐。","圣心涵水镜，即是太平基。"]},{"t":"端平二年端午帖子词 其六 皇帝閤","f":"七言绝句","c":["王师一举下河东，好定规摹继伐功。","入眼宫槐宜夏日，转头关柳易秋风。"]},{"t":"端平二年端午帖子词 其一 皇帝閤","f":"五言绝句","c":["更化开皇极，中兴兆赤符。","节摽千岁历，气协五时图。"]},{"t":"端平二年端午帖子词 其五 贵妃閤","f":"七言绝句","c":["穿莲漏永金铺邃，雪藕衣轻玉殿凉。","好把无邪毋不敬，细挑綵字寿君王。"]},{"t":"端平二年端午帖子词 其二 贵妃閤","f":"五言绝句","c":["萱长宜男草，榴开结子花。","欢声喧令节，庆事属天家。"]},{"t":"端平二年端午帖子词 其四 贵妃閤","f":"七言绝句","c":["裁成宝月翻宫扇，织就祥云制御衣。","朝贺归来无点暑，坐看燕子引雏飞。"]},{"t":"端平二年端午帖子词 其一 贵妃閤","f":"五言绝句","c":["佩袭芳兰碧，钗明宝篆红。","深宫三十六，同被二南风。"]},{"t":"端平二年端午帖子词 其三 贵妃閤","f":"七言绝句","c":["绮疏浸影槐龙转，绣户浮香艾虎垂。","砚冷玉蜍金井水，手抄警戒爱君诗。"]},{"t":"端平三年春帖子词 其一 皇后閤","f":"五言绝句","c":["太液轻澌泮，温明霁日融。","菜流芳荇碧，花颂瑞椒红。"]},{"t":"端平三年春帖子词 其五 皇后閤","f":"七言绝句","c":["殷雷金钥千门邃，斜月璇题六寝深。","禁柳护寒鸦未起，求衣已献晚朝箴。"]},{"t":"端平三年春帖子词 其二 皇后閤","f":"五言绝句","c":["甲观韶光集，禖坛好语传。","思齐男庆百，假乐子宜千。"]},{"t":"端平三年春帖子词 其四 皇后閤","f":"七言绝句","c":["关雎风化冠周南，次第桃夭及葛覃。","农事未兴先献种，女红方起又亲蚕。"]},{"t":"端平三年春帖子词 其三 皇后閤","f":"七言绝句","c":["涂山阴赞夏王化，妫汭密裨虞帝仁。","保合大和无间断，际天蟠地一般春。"]},{"t":"端平三年春帖子词 其五 皇帝閤","f":"七言绝句","c":["东风送喜上天颜，吉语飞来井轸间。","榆塞雪消鸣镝静，柳营月暖击刁闲。"]},{"t":"端平三年春帖子词 其二 皇帝閤","f":"五言绝句","c":["冰天寒色饯，旸谷霁华宾。","生意乾坤满，宸襟一点春。"]},{"t":"端平三年春帖子词 其三 皇帝閤","f":"五言绝句","c":["宽大朝廷诏，中和郡国诗。","欲求跻庆历，先使见淳熙。"]},{"t":"端平三年春帖子词 其四 皇帝閤","f":"七言绝句","c":["唤仗紫宸披晓霭，退朝清燕坐晴霏。","简编有味炉熏永，铃索无声漏箭稀。"]},{"t":"端平三年春帖子词 其六 皇帝閤","f":"七言绝句","c":["麦苗培秀腊前雪，稻种浸芽春后晴。","野老田夫观治象，便从新岁贺升平。"]},{"t":"端平三年春帖子词 其一 皇帝閤","f":"五言绝句","c":["和凤东风转，携龙北斗回。","人间遒铎振，天上兽樽开。"]},{"t":"端平三年春帖子词 其五 贵妃閤","f":"七言绝句","c":["万年枝上綵裁绿，千叶花头酥点红。","镜绶囊丝相映烛，探先半月庆流虹。"]},{"t":"端平三年春帖子词 其一 贵妃閤","f":"五言绝句","c":["梅试催妆粉，兰披入梦香。","迎春占北斗，受福拜东皇。"]},{"t":"端平三年春帖子词 其四 贵妃閤","f":"七言绝句","c":["鳷鹊雪残笼霁景，鵁鶄波暖飏纹漪。","宫中不用催行乐，草木群生各自熙。"]},{"t":"端平三年春帖子词 其二 贵妃閤","f":"五言绝句","c":["象应轩龙次，恩承帝座光。","燕坛风澹荡，蚕馆日舒长。"]},{"t":"端平三年春帖子词 其三 贵妃閤","f":"七言绝句","c":["春透蓬莱碧玉壶，晴窗恭侍宝奎敷。","从容玩画家人卦，取次题箴列女图。"]},{"t":"翠蛟亭 其二","f":"七言绝句","c":["晴雷碾破白云窝，无数林华衮下坡。","好把辘轳翻转着，昆崙顶上卷黄河。"]},{"t":"翠蛟亭 其一","f":"七言绝句","c":["壮杉耄桧护嵌空，飞堕蜿蜒白玉虹。","莫道隔凡元有柱，胡麻流出石矼东。"]},{"t":"鄱江楼晚望","f":"七言绝句","c":["暮雨才收未炙灯，苍鹥掠破岸阴澄。","须臾认得船头竹，始信渔人挂起罾。"]},{"t":"槿花","f":"七言绝句","c":["露径风篱取次芳，朝荣暮悴付流光。","一秋朵朵红相续，比着人情大段长。"]},{"t":"潭毒关","f":"七言绝句","c":["倚天翠壁夹黄流，伛偻呕哑挽上舟。","今古英雄愁绝处，夕阳筹笔驿东头。"]},{"t":"题李参政范殿撰大散关诗后","f":"七言绝句","c":["秦关老月几亏盈，长照诗人白发明。","一死一生沤起灭，未应于此见交情。"]},{"t":"题钟春伯所示周昉明皇对弈图","f":"七言绝句","c":["宝栏十二午阴移，思入云霄落子迟。","当局早知提醒着，危机应不堕蛾眉。"]},{"t":"赠小儿医","f":"七言绝句","c":["忍饥觅句孟东野，守寂草玄杨子云。","囊有遗书无与读，两家恨不早逢君。"]},{"t":"赠石室朱修行 其二","f":"七言绝句","c":["落叶堆中折脚铛，白云煮尽又还生。","洞门黄鹤婆娑舞，留得松风待月明。"]},{"t":"赠石室朱修行 其一","f":"七言绝句","c":["响泉一派落天风，人在浮云柳絮中。","亭午柴关犹未启，碧玲珑底拒霜红。"]},{"t":"赠洪子需 其二","f":"七言绝句","c":["楼倚晴空月满湖，一尘飞不到庭除。","虞初九百浑高阁，且读人间本分书。"]},{"t":"赠洪子需 其一","f":"七言绝句","c":["莫恃青春两颊红，年来我已鬓如蓬。","盘洲野处源流在，早挹文名尉若翁。"]},{"t":"徽州叶司理送冬笋","f":"七言绝句","c":["冻雪晴边白柄镵，浴泥扶出锦绷衫。","定知王谢家苗裔，风味生来便不凡。"]},{"t":"乙酉六月十九日应诏言事九月一日去国一首","f":"七言律诗","c":["黑风吹雨出长安，破帽骚骚怯暮寒。","不得之乎成一事，却因而已失三官。","人心天理推详易，世路交情点检难。","白发老人经事惯，教儿只作博投看。"]},{"t":"丁亥岁朝把笔","f":"七言律诗","c":["鸡唤璇杓一夜东，长天绀碧静无风。","年华老子欢娱里，春事儿曹翰墨中。","脱雪荠芽盘饤绿，晞阳椒蕾酒行红。","赭袍亲上慈明册，正想千官会汉宫。"]},{"t":"七夕","f":"七言律诗","c":["好个牵牛织女天，凄其独夜不成眠。","柳家细婢何能问，太尉粗人祗自怜。","比翼难磨终古恨，妩眉未了宿生缘。","新凉如水谁消得，平等天公也解偏。"]},{"t":"九日复口","f":"七言律诗","c":["凉边未放菊花斑，莫作重阳节物看。","就网买鱼风露重，推篷举酒水天宽。","箭头岁月离弦易，局面功名下着难。","惭愧竟陵江上叟，采菰捣黍鬓毛寒。"]},{"t":"九日阅武预观军容退而纪事","f":"七言律诗","c":["遨头不管菊花寒，簇队晨登上将坛。","戏马台前千古事，筹边楼下万人看。","弓声浏亮秋风劲，旗采精明宿雨乾。","后部铙歌归较晚，雪西烽火报平安。"]},{"t":"九月四日过增口道中","f":"七言律诗","c":["秋光拍塞小村墟，高下人家意自如。","屋底四蚕抽蛹细，墙头三桂着花疏。","握儿早秫酒无限，杓子晚菘齑有馀。","大似元丰年界好，天应容我老樵渔。"]},{"t":"九州山僧房","f":"五言律诗","c":["路突亭依石，林凹渚见沙。","嵚危几岣嵝，深蔚似琅琊。","客倦惊寒思，僧闲忘岁华。","两窗风露影，一树枇杷花。"]},{"t":"二月二十七游仙洞次壁间韵","f":"五言律诗","c":["点脚地维绝，举头天语闻。","瀑泉飞响雪，洞石涌崩云。","缥缈追元放，低回揖郭文。","神清知好在，烟锁绿苔纹。"]},{"t":"八阵图","f":"五言律诗","c":["负卦龟藏尾，鸣皋鹤引吭。","纵横中左右，奇正锐圆方。","石挟孤忠在，江输宿恨长。","无人同领会，搔首立斜阳。"]},{"t":"十月晦过巫山 其二","f":"五言律诗","c":["客里年华老，船头日色曛。","天寒催雨雪，地远隔飞云。","为吏徒三尺，于民未一分。","重惭豪杰士，度外立奇勋。"]},{"t":"十月晦过巫山 其一","f":"五言律诗","c":["巫峡逢初度，平生一段奇。","江山襟抱写，岁月鬓毛知。","神女翻旗下，冯夷叠鼓随。","直须豪举酒，捩柂不妨迟。"]},{"t":"又次及甫渚宫","f":"五言律诗","c":["南楼风物远，西郭市声连。","蝇虎寒窗搏，蜗牛败壁缘。","怀人乔木外，吊古折荷边。","富贵今安在，樵归唤渡船。"]},{"t":"又和忆可庵","f":"七言律诗","c":["耐翁流庆遍仍来，随处烝尝荐笋苔。","但认白云飞一点，便胜黄犊走千回。","屋山早露柤梨熟，墓道秋风菊桂开。","父子相从归展省，岂无野水为添杯。"]},{"t":"又塔院","f":"五言律诗","c":["僧伽传法处，阿育放光时。","到顶直无缝，透心横有枝。","梅间诗凤咮，竹里酒鸱夷。","醉上危层去，空明渺所思。"]},{"t":"又敬和还家","f":"五言律诗","c":["丧家知似狗，生子望如狼。","过尽灯花影，空馀汗竹香。","菊肥人自瘦，发短虑何长。","霜蟹新篘酒，由来苦易忘。"]},{"t":"又敬和还家自喜","f":"七言律诗","c":["溪山鱼鸟识车尘，风日温明试小春。","黄帽青鞋安乐法，芋魁豆荚太平人。","接篱倒着情怀放，蓬沓逢迎气味真。","儿亦梦牵潭上菊，和香细嚼胜猩唇。"]},{"t":"又敬和寓舍","f":"七言律诗","c":["借得卢仝屋数间，不为太窄不为宽。","胸中鹏背三千里，膜外羊肠百八盘。","薜荔水中摽本远，菖蒲石上见花难。","粗茶粝饭随缘过，等作须弥芥子看。"]},{"t":"又答孙正叔","f":"七言律诗","c":["万里西风雁影斜，平安书到鲁家沙。","遣愁白堕须行瓮，报喜乌邪又满车。","老屋打头思钓隐，健舻衔尾认诗家。","道旁啁哳儿童说，有脚阳春向浣花。"]},{"t":"又答景扬","f":"七言律诗","c":["朝家久设礼为罗，小寄禅窗共讲磨。","红锦障泥飞騕袅，黄金宝校琢盘陀。","冰齑荐饭乡风古，雪汁烹茶雅道多。","领取单传心法去，会将佛祖一时呵。"]},{"t":"三日兄弟侍老人展墓归和尊韵","f":"七言律诗","c":["云淡风柔霁色轻，泷冈阡上气和明。","莫思旧日遨头出，且试新年便面行。","饱饭即为君子泰，浊醪不失圣人清。","一翁二季春无尽，更愿诸孙向老成。"]},{"t":"上巳呈子有","f":"七言律诗","c":["隔水梨花豪放尽，安排鼠耳到庭槐。","十分春事杜门过，百色老怀中酒来。","闻丽人行头辄掉，见兰亭帖眼还开。","碧衫玉唾酴醾晚，更倩诗翁着句催。"]},{"t":"夕阳","f":"五言律诗","c":["百丈岗头路，沧凉步夕阳。","石芒轻放屦，草荚紧牵裳。","深紫猴楂熟，疏红马蓼荒。","牧儿良得意，吹笛下牛羊。"]},{"t":"大人和云楼底雪千峰楼头着寓翁梅方开萼绿桃已亚枝红斟浅偏劳劝眠迟不受烘锦城春在眼何暇问蚕丛时四川李制置以荣州见辟辞之也某因用前韵","f":"五言律诗","c":["寄榻高寒地，收心懒散翁。","鸡鸣虚室白，鸦起小窗红。","古操尘弦拂，新诗冻研烘。","桃梅芳意觉，不是去年丛。"]},{"t":"小雪前三日钟冠之约余侍老人行山舟发后洪入杜坞自郑盖庵过阆山趋翔凤山菁山遍览杨坟秀园遂至何山道场山乘兴薄吴兴访玉湖书院水晶境界而归自戊子至庚子阴晴相半胜处辄徘徊赋诗饮酒伟哉观也数诗见后 出阆山","f":"五言律诗","c":["无雨又无日，此行天相之。","荒园遗木老，古隧得峰奇。","霜晚蔬犹剑，风温茗已旗。","行厨何用许，胜处可忘饥。"]},{"t":"小雪前三日钟冠之约余侍老人行山舟发后洪入杜坞自郑盖庵过阆山趋翔凤山菁山遍览杨坟秀园遂至何山道场山乘兴薄吴兴访玉湖书院水晶境界而归自戊子至庚子阴晴相半胜处辄徘徊赋诗饮酒伟哉观也数诗见后 翔凤山资福寺","f":"五言律诗","c":["听雨客无寐，放晴山有灵。","禅关深紫翠，勋庙肃丹青。","鳌负摩云碣，龙扶拱日屏。","真如无尽意，石涧水泠泠。"]},{"t":"小雪前三日钟冠之约余侍老人行山舟发后洪入杜坞自郑盖庵过阆山趋翔凤山菁山遍览杨坟秀园遂至何山道场山乘兴薄吴兴访玉湖书院水晶境界而归自戊子至庚子阴晴相半胜处辄徘徊赋诗饮酒伟哉观也数诗见后 谨和老人凤口遇雨","f":"五言律诗","c":["狂暖酿成雨，逆风摇断桡。","寂谈王舍卫，闷想郁台萧。","游兴孤芒屩，归期数翠翘。","推篷占霁色，木末散声招。"]},{"t":"山中菰生米父老谓丰年之祥用子有韵","f":"五言律诗","c":["秋风菰黍黑，山崦罕闻之。","产瑞摇银海，占丰滟玉池。","芃芃粳合穗，袅袅穄分枝。","却忆官张望，尝新荐一匙。"]},{"t":"山房藏书万三千卷子有赋诗用韵","f":"七言律诗","c":["门巷萧然雀可罗，藏山万卷自研磨。","懒寻玉女登西岳，甘伴金仙坐补陀。","书带草长尘虑少，钵昙花放道缘多。","酒肴问字如相过，引道松间不用呵。"]},{"t":"中春中浣后一日老人挈累下西市寓舍越三日某行感而赋诗呈友人 其二","f":"五言律诗","c":["吐气韶华里，关心晓哢边。","鹧鸪天性在，杜宇世情然。","怒笋和泥煮，殷花蘸乳煎。","须君来共此，已办杖头钱。"]},{"t":"中春中浣后一日老人挈累下西市寓舍越三日某行感而赋诗呈友人 其一","f":"五言律诗","c":["血气危频复，头颅老数奇。","家如缘角鼠，身是脱筒龟。","草树春离列，云山晚蔽亏。","意行随所到，不必问何之。"]},{"t":"中秋秭归岸下","f":"七言律诗","c":["出蜀趋吴第一州，夕凉随意系扁舟。","十分人鲊瓮头月，一片水晶宫里秋。","夜气长存号老鹤，天机自动舞潜虬。","得归到处皆佳思，不问西风解白头。"]},{"t":"中秋楚东对月次曹提管韵","f":"七言律诗","c":["西风一笑话绸缪，白露横江滴滴秋。","天没遮栏金饼上，水无边际玉绳收。","扶将太白酣方适，唤起冯夷舞未休。","今夕明年应更好，夜潮来处倚危楼。"]},{"t":"六月五日集英殿策士从官待宣于内军器库廊","f":"七言律诗","c":["汉廷与目策英豪，投钓知谁首掣鳌。","百日红连纶阁迥，万年枝拂禁城高。","内廊坐永风生席，辇路归迟月映袍。","西抹东涂浑忘却，一絇短雪不堪搔。"]},{"t":"劝农呈丘帅 其一","f":"七言律诗","c":["劭耕好语落西畴，父老逢迎笑点头。","销甲事农官有术，卖薪沽酒我何忧。","黄金深椀频倾倒，白布长衫迭献酬。","飒飒雨华随后乘，安排麦陇十分秋。"]},{"t":"劝农呈丘帅 其二","f":"七言律诗","c":["南楼健目略江皋，淅蔌风沙响鬓毛。","草色不随壕岸断，柳梢恰与女墙高。","碧幢红旆三边帅，羽扇纶巾一世豪。","坐上捷书来猎猎，官军破贼战方鏖。"]},{"t":"午困","f":"七言律诗","c":["故人书断故山离，义重惟穷到处随。","无米胸中元自杵，不蚕鬓底却能丝。","消梅乞与嘲盐贵，苦笋烹来怪酱迟。","亡可柰何安若命，午窗赢得睡便宜。"]},{"t":"太一宫斋祭呈司封吴舍人","f":"七言律诗","c":["宝钥轰霄启玉晨，风恬雪霁净无尘。","东皇太一紫坛晓，世界大千青陆春。","藜杖流光环佩集，锋旗敛影豆笾陈。","乐歌须仗甘泉笔，斧藻天家泰道新。"]},{"t":"太庙致斋","f":"七言律诗","c":["风雨残春晚作晴，宝山深静勃鸠鸣。","云收翠戟龙文润，日透金铺兽面明。","蚕出火时桑正沃，秧抽颖处麦还成。","在天列圣孙谋远，流福人间酿太平。"]},{"t":"开济堂","f":"七言律诗","c":["鱼复平沙涨夕阴，红旗影底老蛟吟。","穷今亘古三分恨，托地撑天一寸心。","过雨断云闲绝壁，凉风归鸟急平林。","江山难着醒时眼，有酒如渑放手斟。"]},{"t":"引镜","f":"五言律诗","c":["水白深还黑，山黄远自青。","纷然无定色，何者是真形。","不坏只太极，长存惟六经。","莫疑晨镜里，黳漆换星星。"]},{"t":"方氏棣华桂丛亭各一首 其一","f":"五言律诗","c":["一忍来百顺，寸私生万殊。","能思根共出，自爱鄂相扶。","夜雨平生约，春风尽日娱。","几家燃豆泣，知愧脊令无。"]},{"t":"方氏棣华桂丛亭各一首 其二","f":"五言律诗","c":["天上广寒种，人间方寸栽。","田三和气溢，窦十庆源开。","色阅风霜在，香包月露来。","八窗秋竞爽，堪覆掌中杯。"]},{"t":"水仙","f":"五言律诗","c":["万卉净如扫，风霜犹典刑。","睟容闲整整，姱节矫亭亭。","几滑铜熏鼎，窗明石砚屏。","窈深人不到，香触梦魂醒。"]},{"t":"水行","f":"五言律诗","c":["岸曲频移柂，巾攲独倚樯。","月分云外影，风进水边凉。","宿鸟树三匝，佳人天一方。","清斯缨可濯，谁为赋沧浪。"]},{"t":"水宿","f":"五言律诗","c":["分席眠鸥渚，庐山梦已通。","蓬声疏密雨，灯影往来风。","我正思吾母，儿应说乃翁。","拥衾天未晓，此味与谁同。"]},{"t":"王火井见过先以诗寄用韵 其二","f":"七言律诗","c":["故人寒踏龙门路，来听深山唱竹枝。","半世向人长落落，几回于我独奇奇。","淡交似水有馀味，薄俗如云无定姿。","一点青灯俱白发，相看不语只心知。"]},{"t":"王火井见过先以诗寄用韵 其一","f":"楚辞体","c":["自期东里先生似，恰与西龙道院宜。","槲叶萧骚秋入画，梅花的皪月供诗。","盟鸥谁是知机早，叹鹤吾犹决计迟。","归去来兮松菊在，故山毋用费文移。"]},{"t":"长宁高守见寄用韵奉酬","f":"七言律诗","c":["呼吸东风养姹婴，翰林非主墨非卿。","吾身元与三才并，此性须存一点明。","盘谷钓鲜深复窈，羌村倾榼浊还清。","久要谁似长宁守，尚记慈恩恶姓名。"]},{"t":"风定船开夜泊柳子口上到荆州尚三程","f":"七言律诗","c":["山远江平眼为开，楚楼西畔即阳台。","金钗短笠风声接，蒸裹燋糟节物来。","鸡唤客程三老起，雁将归梦五更回。","白云飞处西湖近，应买霜螯试泼醅。"]},{"t":"丙戌天基节自至道宫趋宝福院寒甚","f":"五言律诗","c":["朝谒千秋节，攀援万岁藤。","山明松戴雪，涧涩石怀冰。","清壮髯还戟，酸癯面亦棱。","暖寒能破戒，珍重虎溪僧。"]},{"t":"东山次俞紫微止止堂韵","f":"五言律诗","c":["佛法元无法，人谋尽过谋。","说空犹是着，领妙更何求。","径滑松杉古，窗虚水石幽。","琤琤鸣铁里，安处一时休。"]},{"t":"东山怀谢傅用礼灭翁韵","f":"七言律诗","c":["金堂石室旧徜徉，被发依然下大荒。","月送婵娟华落蕊，云移缥缈湿疏篁。","桓伊筝外深情酒，幼度棋边定力香。","往古来今开阖眼，楼头吹面朔风凉。"]},{"t":"东屯","f":"七言律诗","c":["荦确嵚岑转百盘，峡天深处得平宽。","秋风策策蘼花老，暮雨萧萧稻子寒。","仁者乐山心本静，硕人在涧体俱胖。","农家不解诗翁趣，只道丰年了纳官。"]},{"t":"仙鹤楼避暑","f":"五言律诗","c":["孤塔山光寂，危楼岸影斜。","秋声来木末，客思满天涯。","离列高低树，沧茫隐见沙。","夜凉人被酒，乘月快浮家。"]},{"t":"台中听雪","f":"五言律诗","c":["淅沥松厅夜，空山一样声。","冰霜元自劲，水月更添清。","衾薄难留梦，窗虚易得明。","庭乌催奏墨，未晓已先鸣。"]},{"t":"叶主簿挽诗","f":"五言律诗","c":["生理鸱夷子，心期桑苧翁。","行厨脩竹月，坐舰落花风。","雏好才孤凤，行疏忽断鸿。","吴松明远目，一点夕阳红。"]},{"t":"次韵双桂","f":"七言律诗","c":["物理无枯底有荣，一双玉树倚脩楹。","长如拱璧天球在，元共交梨火枣生。","卜筑地连盘谷胜，赋归人占小山清。","昼阴最喜添新绿，时有佳禽自荐名。"]},{"t":"宁宗皇帝挽诗 其二","f":"五言律诗","c":["德粹三灵接，功成万国雍。","方培丰水芑，忽跨鼎湖龙。","庙号追文考，陵名冠世宗。","微臣趋觐晚，洒涕续车攻。"]},{"t":"宁宗皇帝挽诗 其一","f":"五言律诗","c":["虚己尧黄屋，清心汉弋绨。","乾符开太一，坤轸拓全齐。","镇国天球在，宾空宝仗迷。","历年施泽久，四海哭遗黎。"]},{"t":"左蠡","f":"五言律诗","c":["山为飞沙白，江缘涨潦黄。","古今双去鹜，天地一轻航。","隽永还攲枕，牢愁忍别觞。","晴云横不度，何处是柴桑。"]},{"t":"平山","f":"五言律诗","c":["放脚氛埃表，搔头广莫间。","淮分三代水，江护六朝山。","落日苍烟起，秋风白鸟还。","欧韩呼不起，髀满鬓毛斑。"]},{"t":"正月三日同莫干祝法游东西园","f":"七言律诗","c":["探得行春第一筹，南梢花事半将休。","断云不碍远山碧，新月自随江水流。","金谷主人真已矣，玉堂老子尚来不。","丁宁留取蒲城酒，更约东风汗漫游。"]},{"t":"用子有述怀韵为寿","f":"七言律诗","c":["笔力强于二石弓，文场早合擅元戎。","东西涂抹未为老，左右图书那得穷。","三日窥牛酬壮志，十年到凤策奇功。","更须传取长生诀，蜜炬高烧不受风。"]},{"t":"用王司理韵送别 其二","f":"五言律诗","c":["芦花秋摵摵，征思旆悠悠。","歌吹莫愁国，鼓铙熊绎州。","胸奇空盾鼻，胆隽落旄头。","傥有西风雁，频书老故侯。"]},{"t":"用王司理韵送别 其一","f":"五言律诗","c":["亨衢方四十，满谓乃翁如。","为底澼洸药，依然城旦书。","光尘风物里，消息事情初。","束起东西玉，功名富贵馀。"]},{"t":"用伯脩韵迓虞提刑","f":"七言律诗","c":["从来图易必思艰，运甓工夫莫放闲。","万里功名终竟在，百年元气早须还。","安危着眼棋枰外，中否留心弩括间。","寄似匆匆无几语，华阳东去是潼关。"]},{"t":"用吴秘书正月晦韵","f":"七言律诗","c":["揽春群玉写芳怀，次第安排到药苔。","但得斯文留脉在，须教我辈放眉开。","疏风细雨桃花过，竹屋柴门燕子来。","老去湖山无复梦，荷锄西崦觅桤栽。"]},{"t":"用虞提刑见寄诗韵答之 其二","f":"七言律诗","c":["鸡鸣而起一般时，舜蹠殊途觉与迷。","此理天无分厚薄，乃心人自眩东西。","柴门风雨榴花老，草巷烟霏燕子低。","玉汝有书来万里，圣贤不泰不栖栖。"]},{"t":"用虞提刑见寄诗韵答之 其一","f":"楚辞体","c":["有美人兮古锦官，落花芳草几凭栏。","纷纷世故肱三折，忽忽年华指一弹。","诗到考槃须熟讲，易于未济莫轻看。","门前尺雪青灯夜，尚欲从公扣两端。"]},{"t":"用韵答子有","f":"七言律诗","c":["旧雨来人眼底稀，春风独许共襟期。","斜川追古年年早，曲水从今事事奇。","烂熳和诗齐少长，淋漓被酒略崇卑。","惊回蜀道芳时梦，花亚银钗舞竹枝。"]},{"t":"用韵答厉辅卿 其二","f":"五言律诗","c":["南北锦一住，东西岩屡登。","报春梅有信，送酒鹊无凭。","之子能相过，诗名不浪称。","漉冰烹小凤，爽思为渠增。"]},{"t":"用韵答厉辅卿 其一","f":"五言律诗","c":["坐穷无过客，失喜得吾侪。","材逸类淮海，诗清如简斋。","山明知玉气，水涸见霜涯。","期子进此道，为亲生好怀。"]},{"t":"用韵答赵主簿","f":"五言律诗","c":["逸气盖三谢，英词参二班。","飞緌宜北阙，枉驾忽东山。","花妥昼阴寂，絮吹春思闲。","光风知几转，尽付酒杯间。"]},{"t":"用韵答游司直见寄","f":"七言律诗","c":["道在皇王帝霸间，古今同是一人寰。","不愁垂白三千丈，独喜飞黄十二闲。","晚桂荐花熏鼎古，寒松堕子茗瓯斑。","山中风味无人会，赖得新诗起老顽。"]},{"t":"白鹿书院","f":"七言律诗","c":["万绿团阴町疃场，倚凉弦诵玉琅琅。","溪山涵毓中和气，草木薰蒸正大香。","陋巷颜渊何所乐，舞雩曾点若为狂。","懦夫百世闻风起，此去濂溪更有庄。"]},{"t":"石斛","f":"五言律诗","c":["蚱蜢髀多节，蜜蜂脾有香。","藓痕分磥砢，兰颖聚琳琅。","药谱知曾有，诗题得未尝。","瓦盆风弄晚，披拂一襟凉。"]},{"t":"邛杖次韵","f":"七言律诗","c":["槎使携归饷老人，高棱疏节屈中伸。","拨开豺虎凭陵气，摄取蛟龙变化身。","访洗头盆还喜健，伴行脚笠未嫌贫。","一般仙骨清如鹤，倚看沧溟解起尘。"]},{"t":"龙州麸金丹砂到官后民告所得倍于他时喜为赋诗","f":"五言律诗","c":["乳到零陵竭，珠辞合浦行。","地非悭所产，人自晦于征。","砂粒层层长，金麸点点明。","盛衰非自尔，利莫与民争。"]},{"t":"龙池沙涨","f":"五言律诗","c":["龙徙三湫宅，山飞百道洪。","云车风马去，福地洞天空。","苍莽浑沙积，崎岖没径通。","等闲陵谷变，惊倒白头翁。"]},{"t":"龙尾","f":"五言律诗","c":["浅碛苕花紫，平畦芋梗红。","暝收渔筏雨，凉入酒帘风。","客路三年梦，官身两鬓蓬。","谁知龙尾道，却在鹿头东。"]},{"t":"会心","f":"五言律诗","c":["不是非心佛，还疑有漏仙。","朝闻驰鼓起，夜候定钟眠。","浴少衣偏垢，游多袜易穿。","祗将毋不敬，推倒野狐禅。"]},{"t":"先妣忌日发昭化","f":"楚辞体","c":["短棹横秋桔柏矶，青山无尽白云飞。","官三年矣母安在，天一方兮儿欲归。","拱木阴阴闲墓隧，背萱寂寂老庭闱。","呼儿扫驿陈遗像，杯酒炉香泪满衣。"]},{"t":"再用陀字韵","f":"七言律诗","c":["烟霏深处万山罗，闲里工夫岁月磨。","上采纬书乾凿度，下搜杂志薛延陀。","手披不厌薰沉水，心悟何妨涉贝多。","若问尊经阁中事，南丰作记也须呵。"]},{"t":"再和廷迈","f":"七言律诗","c":["步障晴丝夹道青，土桥石磴向西坰。","李乌奴宅空怀古，武阿婆祠懒乞灵。","杜宇一声犹客路，白云万里是亲庭。","只应江水知人意，东下何曾半息停。"]},{"t":"再赋 其二","f":"七言律诗","c":["一出俄经震巽离，盈虚消息取诸随。","盆栽菡萏何时藕，檐挂蜘蛛尽日丝。","左墄右平魂梦远，东岗西崦杖藜迟。","棱棱瘦骨萧萧发，恰与黄冠野服宜。"]},{"t":"再赋 其一","f":"七言律诗","c":["谁为风光管合离，绿阴芳草日相随。","此身百丈牵三峡，吾道千钧系一丝。","力戒荡舟君子适，志期学圃小人迟。","平生客气消磨尽，醉固佳哉醒亦宜。"]},{"t":"刘家江阻风 其二","f":"五言律诗","c":["岁月孤槎转，风波断梗随。","谢三元自惯，巽二莫相欺。","沙岸往来拍，芦林开阖吹。","欠伸呼斗酒，一笑酹冯夷。"]},{"t":"刘家江阻风 其一","f":"五言律诗","c":["动地千牛力，行天万马声。","溟濛迷太极，浩荡送平生。","梦与屏帏兀，心随簋缶倾。","黄头多着缆，作止候三更。"]},{"t":"后溪挽诗 其二","f":"五言律诗","c":["气象融三极，规摹隘九州。","天津朝发轫，野渡晚横舟。","卫道身何爱，忧时死未休。","落花春寂寂，万古蜀江流。"]},{"t":"后溪挽诗 其一","f":"五言律诗","c":["玉佩华裾翠，霜髯睟颊红。","四朝天下老，百世后溪翁。","绿竹猗重较，黄裳美在中。","平生涵养力，于道有全功。"]},{"t":"回龙寺松","f":"五言律诗","c":["环蜀多宜柏，回龙独见松。","似惊前辈落，忽与故人逢。","水石清高骨，风霜老退容。","更须坚晚节，莫洿大夫封。"]},{"t":"孙推内子挽诗","f":"五言律诗","c":["玉立金闺客，家人亦许清。","共听秋塞柝，细剔夜窗檠。","娣袂从渠好，儿襦得我平。","西风吹落叶，不尽夕阳明。"]},{"t":"安泰","f":"七言律诗","c":["不是官身是客身，下车随意踏芳尘。","空濛山色雨非雨，冷淡花梢春自春。","裘弊黑貂犹耐老，褐移紫凤未全贫。","青帘垂脚游丝外，到处东风似故人。"]},{"t":"岁杪用韵 其二","f":"五言律诗","c":["黄麾春簇仗，梦不到东华。","瓦研磨冰叶，砖炉煮雪花。","穷甘猿帐卧，老倦犊辕挝。","冻解光风转，晴波拍两涯。"]},{"t":"岁杪用韵 其一","f":"五言律诗","c":["日月磨心绪，风霜染鬓华。","历看新岁草，梅忆旧年花。","浊酒供僛舞，清歌应掺挝。","阿咸多事在，犹问老生涯。"]},{"t":"廷迈留少城和初入西龙道院诗来用韵答之","f":"词","c":["雪锦楼高眼易寒，春风朵朵似长安。","终年避事宁为客，到处寻诗胜觅官。","金凿落边檛蹀躞，玉参差里舞?跚。","华灯变尽归来晚，回首西涪可忍看。"]},{"t":"次及甫入峡杂咏 峡口","f":"五言律诗","c":["山隘留天少，江迂占地多。","风梢猿自挂，露草虎曾过。","坐客犹吴语，行人尽楚歌。","川妃澜浪甚，着语试谁何。"]},{"t":"次及甫见寄 其二","f":"五言律诗","c":["燕颔非无相，鸢肩会有时。","三薰珍敝帚，一笑玩征棋。","松菊吾家物，衡茅厥父基。","青峰帘独捲，细和式微诗。"]},{"t":"次及甫见寄 其一","f":"五言律诗","c":["文采晁无咎，襟期李伯时。","昔为钩直钓，今是劫忙棋。","弩谷深无路，盘堤薄有基。","广文如我冷，两地四愁诗。"]},{"t":"次及甫即事","f":"五言律诗","c":["万里西征路，同君汗漫期。","吴歈花里曲，楚些菊边词。","问学千鸡蹠，功名五羖皮。","目前姑置此，多办峡江诗。"]},{"t":"次及甫觉寒","f":"五言律诗","c":["霜勒衾如水，寒于客有期。","不成神女梦，空赋外孙词。","瓮暖宜桑落，冠凉怯竹皮。","悬知鄱水上，冷落扊扅诗。"]},{"t":"次及甫韵送致远别","f":"七言律诗","c":["塞尘没没马萧萧，世事今朝异昨朝。","为羡白鸥何浩荡，却思斥鴳亦逍遥。","平沙露碛江波敛，远树明堤野雾销。","快着扁舟归教子，胜渠满屋贮胡椒。"]},{"t":"次子有下第韵","f":"七言律诗","c":["东风换骨立成仙，五色终迷自古然。","龙变未符今举谶，鹤来当验后科缘。","情如中酒宜亲酒，命合腰钱会有钱。","许买娉婷供老伴，不妨迟得两三年。"]},{"t":"次仲禹迓叔禹西归韵 其二","f":"七言律诗","c":["万里春风一札书，锦幢绣旆二难俱。","殷红荔子武侯渡，深碧藕花房相湖。","家庆盛于群玉府，身名荣过执金吾。","人生信是团栾好，我亦归谋种芋区。"]},{"t":"次仲禹迓叔禹西归韵 其一","f":"七言律诗","c":["坡颍风流几许年，依然夜雨落花边。","白头故媪釜忘轑，红颊诸孙衣解牵。","聚雁沙平江百折，养鹅水暖柳三眠。","行厨洗玉更为寿，父老来看许近前。"]},{"t":"次同年王火井不遇之韵","f":"七言律诗","c":["题遍慈恩最上层，青云涂辙几人升。","一经秋雨禾方穟，未到春风海亦冰。","闹里功名多目论，淡中气味独心朋。","苍苔不扫芙蓉老，有客敲门自出应。"]},{"t":"次李绵州和丁兴元韵 其二","f":"七言律诗","c":["梅花已是隔年香，投老何能面复光。","求则得之青籸饭，归斯受矣白云乡。","果柑微似温生乳，阆柿多于处着霜。","扶起东南风物梦，举觞目送去鸿翔。"]},{"t":"次杨泸南以前区字韵送行 其二","f":"七言律诗","c":["万里来鸿未有书，社前归燕与人俱。","涨痕落后杭巫峡，风力高时略太湖。","深愧平生嗟靖节，一匡天下望夷吾。","延英入定中兴业，早震天声到鬼区。"]},{"t":"次杨泸南以前区字韵送行 其一","f":"七言律诗","c":["水稳风凉快长年，归帆东指白云边。","落花款段儿能御，荐草乌犍手自牵。","蜀口戍兵谁饱饭，淮头编户几安眠。","野人只愿群贤进，辐凑良筹到上前。"]},{"t":"次叔厚韵","f":"七言律诗","c":["梦断红尘踏九衢，云山佳处借楼居。","采将瓠叶随宜煮，拾得榴皮信意书。","未问我今忘我世，须知吾本爱吾庐。","黄公垆在花阴里，磊砢从君一破除。"]},{"t":"次洪漕韵 其二","f":"七言律诗","c":["和月梅花共一寒，兜牟未必尽粗官。","醉来抱膝吟梁父，睡起搔头著说难。","富贵冰山何用倚，功名盘石自须钻。","朔风衰草腥狐兔，猎火归鞭夹市看。"]},{"t":"次洪漕韵 其一","f":"七言律诗","c":["塞垣拥雪髑髅寒，多少将军博美官。","莫恨知心今世鲜，须知行道古来难。","时穷地狭何能舞，命好天高亦可钻。","此理乘除应会得，梅边索酒笑相看。"]},{"t":"次费伯矩护印道中韵","f":"七言律诗","c":["合着丝絇侍建章，却随靴裤踏苍凉。","灯前针线为谁好，镜里黛铅如许忙。","野水无心鸥等伍，秋风有味菊颜行。","到头灵运终成佛，妙境须闻戒定香。"]},{"t":"次徐云叟赋桃源无脚桥","f":"七言律诗","c":["经始西风八月秋，桃花春涨已无忧。","横飞阁道虚空度，直放银河自在流。","倚岸斜看疑是洞，循坡稳上认为楼。","遍行吴蜀今才识，却笑浮桥谩造舟。"]},{"t":"次徐隆庆寿诗韵 其二","f":"七言律诗","c":["史君笔斡万牛回，脚底春风舌底雷。","一夜剧谈逢野阆，百年高谊见欧梅。","客心衮衮江流去，老色翩翩岁事来。","堕地渠侬天已定，酒边赢得笑颜开。"]},{"t":"次徐隆庆寿诗韵 其一","f":"七言律诗","c":["牛奋箕张小丙申，熟知命驳不能纯。","年来颇怪刀头蜜，老去难供席上珍。","闯霭千章森戟纛，鏖风万壑绎韶钧。","剑山拾得商山橘，醉共仙翁脯白麟。"]},{"t":"次黄宰早春韵","f":"五言律诗","c":["胜里春来早，迟君秉烛游。","煖如三月暮，香老百花头。","心事付桑落，风光催栗留。","人生行乐耳，任命不须求。"]},{"t":"次程岳州廷迈春行昨访天梯佛龛今约乌奴","f":"七言律诗","c":["汗血嘶风草正青，眼中万马敛春坰。","檄书纵不烦师鲁，荐藁犹当出古灵。","杜若扶疏明远渚，荼蘼猗靡馥中庭。","天梯行遍乌奴去，到手深杯莫暂停。"]},{"t":"次韵七夕","f":"五言律诗","c":["弄巧拙逾甚，合欢愁转多。","擘金盟似海，搔玉泪成河。","天运真旋磨，人生特掷梭。","身闲凉月好，且与醉无何。"]},{"t":"次韵可庵梅","f":"七言律诗","c":["点雪非耶果是耶，紫千红万未曾芽。","苍苔有晕龙钟树，幽谷无人自在花。","地暖孤鸿来索伴，天空双鹭下通家。","诗翁快整春风脚，山路霜泥踏马牙。"]},{"t":"次韵西山","f":"七言律诗","c":["山深莫道得春迟，云漏晴光已大奇。","夹径幽香吹艾纳，隔林绝艳点燕支。","一川远近迷渔屋，两市东西认酒旗。","锦野着亭坡老后，曾来可惜独无诗。"]},{"t":"次韵夏日","f":"五言律诗","c":["乍晴云更黑，顿冷日如青。","饱饭真成蠹，幽居又见萤。","灯光翻露柱，琴叠舞黄庭。","猛作逃儒去，沉酣几个醒。"]},{"t":"次韵夏日","f":"词","c":["秧青水白四郊同，召雨无烦访守宫。","槐叶煮?随市俗，莲花捣曲称家风。","过从久谢三千客，嬉戏长娱七十翁。","已是太平农圃老，更揩两眼看升中。"]},{"t":"次韵高蓼","f":"七言律诗","c":["隰荭照眼似船窗，只欠沙头野鸭双。","花引穟垂丹作佩，叶扶节起翠为幢。","妇收滋味归羹鼎，儿挹馨香赴酒缸。","老我为渠牵午梦，白蘋风冷钓烟江。"]},{"t":"次韵曹提管梅","f":"七言律诗","c":["凌寒峭立向庭除，晋宋渊明汉二疏。","面冷不堪相妩媚，心清聊为一轩渠。","月来月去香仍在，春少春多意自如。","皎洁孤芳谁与共，作诗我欲寄东徐。"]},{"t":"次韵曹提管楚东之作","f":"七言律诗","c":["萧骚两岸落秋蓬，楚水西流不肯东。","好酒但须知妇有，新凉莫问与谁同。","片心置向嚚尘外，万事留将醉眼中。","喜得建安标格在，何曾诗解使人穷。"]},{"t":"次韵遣怀","f":"五言律诗","c":["不用忧春雨，时来百草芳。","猫头肥可锸，雀舌嫩堪囊。","旧酒闻香烈，新诗索味长。","樱桃空落去，吾老白云乡。"]},{"t":"次缪仲右韵 其二","f":"五言律诗","c":["窗暖杨花扑，庭空燕子过。","年侵欢易减，春恼病宜多。","搅涕论兵事，扶头读凯歌。","日来能饮未，正好醉亡何。"]},{"t":"次缪仲右韵 其一","f":"五言律诗","c":["心绪千丝结，年华一鸟过。","可人元自少，知己不须多。","咄咄君休怪，呜呜我亦歌。","将军浑健在，醉尉莫谁何。"]},{"t":"江陵","f":"五言律诗","c":["三海先声壮，重城大势连。","竹为人世界，灯结水因缘。","风物诗囊里，英雄泪眼边。","江平洲露碧，沙市稳开船。"]},{"t":"汤泉","f":"五言律诗","c":["水府燃犀处，扶桑浴日时。","能观雷复地，始信坎生离。","净垢元无着，温凉祇自知。","骊山殷鉴在，莫受阿环缁。"]},{"t":"百合花","f":"五言律诗","c":["日月飞双毂，如何驻黑头。","才看敷密友，又见拆彊仇。","叶聚棱棱峭，花垂娜娜稠。","晚凉芬烈甚，欲睡更迟留。"]},{"t":"老人生朝为寿","f":"七言律诗","c":["迎侍京华又见春，天时人事一番新。","丙申儿遇丙申岁，己卯爷逢己卯辰。","本分法门行得熟，长生样子学来真。","斑衣奉酒多为寿，满眼光风正可人。"]},{"t":"老人晚得女真真又曾孙女金华皆再周而殇葬塔院后今春焚化用前韵赋诗谨和","f":"七言律诗","c":["窣波影里诵陀伽，古佛灯笼护绛纱。","智慧竭罗虽正果，慈悲妙善亦空花。","怕寒婉娈初拳蕨，望雨醒松细舌茶。","节物感人还自解，有儿何用女当家。"]},{"t":"老人赋郑医芝隐楼敬次韵","f":"五言律诗","c":["鹊经心诀在，鸿宝肘方全。","为问春痟首，何如夏胁肩。","楼居高进月，园涉细疏泉。","学得种芝法，疑君今稚川。"]},{"t":"自和","f":"七言律诗","c":["得寮便住似西资，谁暇安巢更择枝。","閤密不妨中酒圣，楼明大好养书痴。","志公分料存刀尺，庞老家风欠笊篱。","大厦千间宵八尺，傍人莫笑太穷猗。"]},{"t":"至节前一日游汪茫田","f":"七言律诗","c":["圣主亲郊肸蚃通，风恬日霁作春容。","好从辇路听清跸，却向深山把瘦筇。","樵子径随萝薜上，道人屋借竹茅封。","一杯旋煮山泉荡，浣尽平生磊砢胸。"]},{"t":"至节前十日游胜因寺","f":"五言律诗","c":["霜霁午曦暖，潦收沙路晞。","束山知寺古，避客怪僧稀。","箨滑涉危屐，藤钩穿密衣。","月黄风不动，灯火虹桥归。"]},{"t":"行三盘蟆颐栈道 其三","f":"五言律诗","c":["虎爪滩头棹，蟆颐阁上车。","危机知略似，薄命听何如。","鸬筏陵飞景，鸠巢架太虚。","乾坤真一阱，着眼莫踌躇。"]},{"t":"行三盘蟆颐栈道 其二","f":"五言律诗","c":["息女頩相问，危途骨欲摧。","儿知缘底去，耶自为官来。","野圃榴多子，山田芋有魁。","乞归吾计决，一粲且传杯。"]},{"t":"行三盘蟆颐栈道 其一","f":"五言律诗","c":["栈险涎鱼蛤，梯危啸虎貙。","室人交谪我，客子倍愁予。","后殿推腰上，前行掉臂呼。","龙眠如得见，写作赴州图。"]},{"t":"西龙道院","f":"七言律诗","c":["溪影山光浸晓寒，空庭人马报平安。","梦回非想天中界，身是无怀国里官。","桑葚青红鸠澒洞，麦花开落雉蹒跚。","好班嘉定中兴诏，尽与蓬婆滴博看。"]},{"t":"观物 其二","f":"五言律诗","c":["薄命天元定，深居日转长。","塔铃空洛度，车铎惯琅珰。","笋长竹还老，莲迟荷自香。","羡他雏又乳，双燕胜春忙。"]},{"t":"观物 其一","f":"五言律诗","c":["饱饭茶瓯罢，闲观万物情。","狗加狮立号，猫冒虎为名。","故沼慈姑王，新畦腐婢荣。","蝉从何许变，忽送出林声。"]},{"t":"遇风出陆金陵道中次程及甫韵","f":"七言律诗","c":["留滞周南命使然，莫疑上水逆风船。","乡山故故随人后，客月依依堕我前。","半夜索樽同决计，五更回柂不成眠。","笋舆吹面新凉入，须信封姨正自贤。"]},{"t":"过四望山","f":"五言律诗","c":["人远鹭孤立，湖平天四垂。","柂移船解语，帘舞酒求知。","望眼倾三笑，骚吟寄九思。","今宵吾计得，解鳖荐鸱夷。"]},{"t":"伯矩同登牛头","f":"五言律诗","c":["两翼城包险，三分寺占奇。","市嚣芳草隔，古意落花知。","岁熟人情乐，时清物态熙。","江山输眼底，尽是太平诗。"]},{"t":"何正言挽诗","f":"五言律诗","c":["隽手芥拾紫，忠肝蒲伏青。","婴龙云气直，缚虎雪毛腥。","炊枕梦何短，书棺名更馨。","眇然人物几，墓草涕交零。"]},{"t":"何正言母安人挽诗","f":"五言律诗","c":["凤采生丹穴，萤光聚绛帏。","两登黄甲去，一佩皂囊归。","萱老悲方切，兰枯梦又非。","青山秋寂历，客泪不胜挥。"]},{"t":"初夏","f":"五言律诗","c":["鹤帐华缨绝，牛蹊老屐穿。","薄晴生晚哢，深绿护馀妍。","万卷不堪煮，百怀空自煎。","朱樱黄苦笋，小酌便陶然。"]},{"t":"初夏即事一首谢俞德远惠茶","f":"七言律诗","c":["病眼昏花懒读书，闭门恬养冉溪愚。","一帘草色蛤呼伴，四壁树阴鸡护雏。","已是归来何用引，本无太极不须图。","小团自汲新泉试，凉满松风石铫炉。"]},{"t":"初酿","f":"五言律诗","c":["手臼登新秫，头缸试嫩醪。","蒲城寒信早，栗里旷怀高。","重熟鱼沾面，微生蟹带糟。","老侬元不饮，随喜亦陶陶。"]},{"t":"呈同行诸丈","f":"五言律诗","c":["秋风俱白发，万里锦城官。","箭贯双雕易，琴随一鹤难。","国宽同是福，民病独何安。","前见乖崖老，烦君举似看。"]},{"t":"寿邹茶使 其二","f":"七言律诗","c":["手挈蓬弧挂井参，筹边楼下瑞云深。","传将绝学圣贤脉，会得初阳天地心。","议论文章胸万甲，功名富贵腹三壬。","春风禁柳东华路，扈驾催行荔子金。"]},{"t":"寿邹茶使 其一","f":"七言律诗","c":["鹤雁旌旗导紫軿，方瞳秋水照人明。","泰山可碎胆常定，沧海自浑心转清。","万事至公如正献，片言不妄即元城。","擎天正要坚牢柱，长与皇家植太平。"]},{"t":"岑公洞","f":"五言律诗","c":["洞从开辟有，翁独擅真清。","磴古苍苔涩，岩空细溜明。","谁刊新即事，尽剔旧题名。","太息今犹古，江山不世情。"]},{"t":"应提刑招饮北山","f":"五言律诗","c":["万绿梢头眼，双江合处城。","山如人有立，水与市俱横。","啼鸟春风暖，飞花晚照明。","笙歌推使去，缓屧当车行。"]},{"t":"李致远母夫人挽诗 其二","f":"五言律诗","c":["日与夫人子，相随若弟兄。","羡渠犹有母，使我欲无生。","未病思求药，方餐念遗羹。","此情今已矣，泪雨待同倾。"]},{"t":"李致远母夫人挽诗 其一","f":"五言律诗","c":["有子何蕃似，悬知母训贤。","市赊留客酒，邻贷买书钱。","苦过莲心后，甜回蔗境边。","一朝风木憾，谁与问苍天。"]},{"t":"杏","f":"七言律诗","c":["万山筑底作春妍，一树繁红直几钱。","深院日长来燕后，平池水暖浴鹅天。","弦歌礼乐诗书地，榜帖功名富贵天。","儿辈对花须自勉，莫教空恼少陵颠。"]},{"t":"社前一日点检山房用呵字韵","f":"七言律诗","c":["不论塌扱与娄罗，判却风光屐齿磨。","老柳强颜翻拓跋，新禽满意奏娑陀。","山如欲雨何妨住，僧不能禅亦足多。","须信斯文天未丧，龙蛇虎豹底烦呵。"]},{"t":"花狮","f":"五言律诗","c":["雪氄吾家虥，知亲翰墨妍。","渴来趋研饮，饱去枕书眠。","弄影窥清镜，收声听素弦。","最能持大体，鼠辈任便儇。"]},{"t":"谷帘泉","f":"七言律诗","c":["山椒飞派落寒空，斗水曾收第一功。","万马铁衣行夜雪，六虬银甲动秋风。","分甘晚到玉川子，知味早输桑苧翁。","手弄潺湲坐盘石，苍凉新月上孤桐。"]},{"t":"迎秋","f":"七言律诗","c":["热不能堪又便秋，天公底暇与人谋。","形容如许马非马，气力几何牛戴牛。","勃勃松梢云片起，琤琤藕叶雨声留。","新凉收拾归歌板，钿合金钗万古愁。"]},{"t":"闲居","f":"五言律诗","c":["暑设青綀幕，晴更皂葛巾。","家贫犹气象，人老亦精神。","蜂闹花生计，蛾翾茧化身。","静中观物变，同是一天真。"]},{"t":"侄寿叔祖","f":"七言律诗","c":["鹊噪梅梢喜报晴，催开几叶砌边蓂。","和薰爱日如春日，光动文星映寿星。","宾客称觞应满座，儿孙戏綵自盈庭。","萱堂幸继芝兰末，仰祝百千龟鹤龄。"]},{"t":"和礼灭翁感钱氏旧事","f":"七言律诗","c":["民不知兵物自华，表忠消得老碑誇。","虎符龙节故王国，凤舞鸾飞今帝家。","遗庙断垣低槲叶，荒村旧井湿桐花。","冯夷尚怕潮头弩，一望西兴渡口沙。"]},{"t":"和何伯温见寄 其二","f":"七言律诗","c":["青山流水晓葱胧，读遍黄庭万境空。","羔瓮无缘浇舌本，貘屏有分护头风。","人谋历历既未济，民力班班大小东。","陶写此怀须好句，殷勤时与寄来鸿。"]},{"t":"和何伯温见寄 其一","f":"七言律诗","c":["问字无人过草堂，昨非今是两俱忘。","鹤何肮脏寒方警，梅许凄凉静更香。","万古江山穷太白，一帘风月老张苍。","多君不作炎凉语，识我平生铁石肠。"]},{"t":"和何特夫见寄","f":"七言律诗","c":["人从万里蜀天归，御柳藏鸦絮又飞。","风细炉熏摇穗直，日长漏箭出花稀。","九重旰食图无逸，四塞宵征赋采薇。","爱国书生心更苦，夜占列象候璿玑。"]},{"t":"和虞仲易送行 其二","f":"五言律诗","c":["岁月双蓬鬓，风沙一老兵。","气惟凭义养，命不与穷争。","鼎正中边沸，船须左右平。","半筹无可画，空赋洗兵行。"]},{"t":"和虞仲易送行 其一","f":"五言律诗","c":["霜晓沧江路，梅花对此君。","清明涵止水，变灭送浮云。","论事强人意，挥毫张我军。","雍公衣钵在，好策后来勋。"]},{"t":"和雪","f":"七言律诗","c":["肃容盛气下璇霄，不作投壶玉女娇。","坡老堂前微扑面，伊川门外骤齐腰。","得风还解掀天起，带雨才能控地飘。","无限陈根生意动，早看绿长后园蕉。"]},{"t":"和黄伯渊见寄 其二","f":"七言律诗","c":["锦野西头始识君，便期垩鼻着风斤。","馀甘到底有遗味，薝卜本来无异芬。","忽忽又弦凉榭月，亭亭还合暮山云。","玉泉道士穷于我，也买新鹅约右军。"]},{"t":"和黄伯渊见寄 其一","f":"七言律诗","c":["流转风光不暂违，等无地角与天涯。","故人书到几青李，生面客来时紫芝。","穷里埋头倾哑酒，凉边趁手应盲棋。","寂寥简短君应笑，郎罢吟诗囝和诗。"]},{"t":"和黄宰木犀","f":"七言律诗","c":["春风花事数河阳，又见玲珑糁缀黄。","万斛香添秋酝藉，十分凉借月容光。","熏奁拾取留长挹，汤鼎煎来得细尝。","须信小山标致别，从渠涂额学宫妆。"]},{"t":"和程教元日韵","f":"七言律诗","c":["晓云三素过天东，早送韶华入万红。","枍诣霜寒迟景转，昆明太液薄澌融。","憨痴官事龟生手，泰定天光漆点瞳。","柏叶更须随酒进，醉乡有地爵无功。"]},{"t":"垂去","f":"五言律诗","c":["凤凰知细德，鸥鸟识机心。","物理固如此，世情非特今。","足缨清与浊，厉揭浅和深。","觉破从前梦，长歌月满襟。"]},{"t":"夜坐","f":"五言律诗","c":["夜永难为睡，群儿坐伴翁。","漉齑冰瓮碧，撚豆雪炉红。","清诵听还隽，闲谈笑又烘。","安排明蚤供，荠长后园丛。"]},{"t":"夜读夷坚放卷偶成","f":"七言律诗","c":["敛卷惊嗟语幻哤，搔头危坐对明缸。","梧桐细语秋传信，络纬长鸣月上窗。","浊酒不多双耳热，妙香无尽寸心降。","家山未得平安报，飞梦东归拜老庞。"]},{"t":"奉使燕山回早行书事","f":"七言律诗","c":["露满中庭月满天，秋来怀抱转悽然。","客程恨不日千里，归思乱如云一川。","故国伤心那忍说，遗民望眼几回穿。","当家旧事堪垂泪，海上看牛十五年。"]},{"t":"宝云庵戒师","f":"七言律诗","c":["钟山好住苦弗住，驮岭难居真欲居。","出地入天须任我，来今去古不关渠。","万由旬上起肤寸，一刹那间弥太虚。","识得鬘华云体段，妙高高处坐如如。"]},{"t":"岸行","f":"七言律诗","c":["少年血气暗消磨，盎盎阳春保大和。","已放杏花风味短，未酸梅子典刑多。","一官满去鱼无饵，万里归来燕有窠。","但愿时平蚕麦好，免教人问蜀如何。"]},{"t":"泥溪 其二","f":"五言律诗","c":["左计来行险，强名为爱奇。","一家川䖃苴，三顿豆离萁。","压架龙门石，撑囊剑阁诗。","扁舟归计足，不问鹤和龟。"]},{"t":"泥溪 其一","f":"五言律诗","c":["沙路缘江曲，斜阳塞轿明。","晚花酣晕浅，平水笑窝轻。","喜荫时休驾，疑昏屡问程。","谁家刚齐饼，味过八珍烹。"]},{"t":"狐鼠","f":"五言律诗","c":["狐鼠擅一窟，虎蛇行九逵。","不论天有眼，但管地无皮。","吏鹜肥如瓠，民鱼烂欲糜。","交征谁敢问，空想素丝诗。"]},{"t":"罗解元母胡氏挽诗","f":"五言律诗","c":["三世不异爨，一门皆力书。","此风今所少，他行特其馀。","藻锜明疏牖，萱窝护碧除。","春光元自在，遗梦杳安舆。"]},{"t":"罗察院父瑞桂堂","f":"七言律诗","c":["老仙方寸长黄芽，百顺薰蒸到物华。","移得广寒宫里种，开将后土庙中花。","诗书根蒂圣贤脉，忠孝馨香今古牙。","富贵傥来馀事耳，化工深意属君家。"]},{"t":"诗告至李汉州","f":"七言律诗","c":["驿奴莫问客为谁，但报房湖水石知。","象鼻卷筒和月吸，凤膺横玉倚风吹。","江淮消息愁端压，关洛功名老色欺。","陶写此情须会得，行厨催唤莫教迟。"]},{"t":"雨","f":"五言律诗","c":["夥颐秋后雨，暝些晚来凉。","夹市崩崖赤，环城涨潦黄。","随宜梨栗熟，满意黍荞香。","白鹭追红鹤，归飞作个忙。"]},{"t":"俞提举挽诗 其二","f":"五言律诗","c":["苍鹤孤山晓，黄花栗里秋。","一身虽物外，万国尚眉头。","遗老几何在，耆英只么休。","问天天不语，江阔莫云愁。"]},{"t":"俞提举挽诗 其一","f":"五言律诗","c":["展也万夫特，翛然山泽臞。","朔风空汴泗，春水渺淮湖。","筹驿尹师鲁，诗坛梅圣俞。","绣衣归老去，有韫不轻沽。"]},{"t":"春日即事 其二","f":"七言律诗","c":["黄奶扶春梦觉来，禅心已堕老黄梅。","沾沾桃叶相先发，寂寂梨花未肯开。","抱案并无钳纸请，索书时有打门催。","人生消得韶华几，两鬓霜根不待栽。"]},{"t":"春日即事 其一","f":"七言律诗","c":["杨柳黄黄燕子来，梅花落尽已青梅。","一年春事闭门过，万里客怀呼酒开。","西土逖哉鸿雁断，东方明矣子规催。","海棠多买燕宫本，归去家山手自栽。"]},{"t":"春行","f":"七言律诗","c":["百舌梢头一半春，日长无处着闲心。","推枰竞欲投机早，结眊谁知用意深。","梅子胚胎盐里味，桐花摆布蜜边阴。","东皋西崦行几遍，软脚踉蹡索酒斟。"]},{"t":"春行次韵","f":"五言律诗","c":["拂开芳草碧，坐断落花红。","世味觥筹外，年华带眼中。","六州空铸铁，万物任为铜。","有鷕桑畴雉，逢时会长雄。"]},{"t":"春事","f":"七言律诗","c":["莫为春愁两鬓翁，管愁元不属春风。","深黄杨柳夕阳外，淡白杏花明月中。","大自在身天地并，妙光明性圣愚同。","鸣鸠乳燕相料理，融得从前万虑空。"]},{"t":"春雪","f":"五言律诗","c":["甲子乾飞雨，元宵湿陨星。","风柔行阵阵，月淡下亭亭。","木笔侵凌碧，来牟掩映青。","东皇收拾急，暖涨赴沧溟。"]},{"t":"昭化","f":"五言律诗","c":["梅子收霖雨，榆花断瘴烟。","浓云明白鸟，深草暗乌犍。","岁月滩声里，家山客枕边。","老来圭角尽，戒得是韦弦。"]},{"t":"柳","f":"七言律诗","c":["天机日与物华新，妩绿柔黄触拨人。","精采只消些子雨，腰肢无着许多春。","兴亡萤苑迷楼梦，荣辱孤山曲院尘。","醒眼年来浑看破，万缘分定不须颦。"]},{"t":"柳用前韵","f":"七言律诗","c":["菀彼烟丝一样新，依然面目我陈人。","只疑大造元无物，岂料深山亦有春。","尽日三眠浑得意，随风万舞不惊尘。","长长短短亭前路，肯与渠侬管笑颦。"]},{"t":"洗研","f":"五言律诗","c":["自洗洮州绿，闲题柿叶红。","一尘空水月，百念老霜风。","钝菊凄犹蕾，颠桃艳已丛。","斡流千万变，谁实主鸿濛。"]},{"t":"洪园洗心堂饮中偶成","f":"五言律诗","c":["官事何时了，抽身朱墨丛。","未霜乌桕赤，得日紫薇红。","山势西南缺，湖光左右通。","引将丝竹却，洗耳听松风。"]},{"t":"省中和何子温见寄","f":"七言律诗","c":["东风婉娩燕来双，禁漏无声万绿香。","宝鸭炷云朝太紫，玉蜍挹露校铅黄。","圣贤不断千年脉，宇宙长存一点光。","老鹤也知虚静好，夜深踏月上脩廊。"]},{"t":"省闱试士","f":"七言律诗","c":["东风席帽快行催，浑为天家造士来。","捧诏九霄云气湿，分题五色日华开。","拣金沙里须精鉴，脱颖囊中尽异材。","容受直言天子圣，好听胪唱响春雷。"]},{"t":"祖母哀挽 其二","f":"五言律诗","c":["叠綵春风里，含饴爱独深。","卷卷行己训，历历读书箴。","长忆违离语，难酬侍养心。","微官稽执绋，东望泪盈襟。"]},{"t":"祖母哀挽 其一","f":"五言律诗","c":["我祖当家始，零丁只影存。","根芽惟大母，枝叶又曾孙。","触少心犹惕，慈多语易温。","德尊年亦称，消得诰花恩。"]},{"t":"秋怀 其二","f":"五言律诗","c":["鹦鹉琵琶恨，融归十四弦。","拨寒红玉笋，拍暖绣金莲。","梅影春风里，茶声雪水边。","自怜还自笑，星发照婵娟。"]},{"t":"秋怀 其一","f":"五言律诗","c":["素节垂垂杪，衰怀拍拍丛。","风乾梧叶白，霜老菊花红。","理曲多添瘦，停诗不减穷。","出寻空阔处，揩眼送飞鸿。"]},{"t":"秋夜","f":"五言律诗","c":["一日一番雨，三更三昧凉。","桐边青弄影，荷底静留香。","俗物刺人眼，世情冰我肠。","关山何处笛，落月照胡床。"]},{"t":"荆公","f":"七言律诗","c":["君臣一德盛熙宁，厌故趋新用六经。","但怪画图来郑侠，何期奏议出唐坰。","掌中大地山河舞，舌底中原草木腥。","养就祸胎身始去，依然钟阜向人青。"]},{"t":"荠馄饨","f":"五言律诗","c":["嫩斸苔边绿，甘包雪里春。","萧家汤是祖，束叟饼为邻。","混沌函三极，冲和贮一真。","日斜摩腹睡，自谓葛天民。"]},{"t":"追和及甫雪","f":"七言律诗","c":["胚腪造化妙天家，趁得辛夷未着花。","浊水淤泥还絮白，枯株朽树亦芳华。","长空光眩鸣皋鹤，厚地寒侵入宇蛇。","钜竹南墙清绝甚，一编孟子一瓯茶。"]},{"t":"送王崇庆得樽字","f":"五言律诗","c":["白苧笼轻暑，红榴照别樽。","两帆先后去，一水古今存。","玉札须多蓄，金瓯莫点痕。","相期黄卷里，培植太平根。"]},{"t":"送张行父守赣 其二","f":"五言律诗","c":["南斗一帆外，西风千骑头。","莫嗟中落落，须感上休休。","贾谊词林晓，陈蕃墓草秋。","经行拚斗酒，为浣古今愁。"]},{"t":"送张行父守赣 其一","f":"五言律诗","c":["觉是圣贤脉，复为天地根。","典刑诸老尽，文献几家存。","露下鹤先警，风高鸿独骞。","一时京洛价，知有魏公孙。"]},{"t":"送李致远安远簿 其二","f":"五言律诗","c":["与我迭知己，喜君初得官。","时来宁论晚，身健莫辞难。","访雪牵魂梦，停云寄肺肝。","斯文元气在，努力好加餐。"]},{"t":"送李致远安远簿 其一","f":"五言律诗","c":["四海几青眼，五车今白头。","信天投矮屋，觅地起岑楼。","山迥风烟合，江平潦雾收。","谁欤人物计，留取备枚邹。"]},{"t":"送杜阳安奉亲还蜀 其二","f":"五言律诗","c":["买我归吴棹，扬君溯蜀旃。","虽为万里别，端有一家缘。","腊雪添新涨，春风减旧绵。","江山随处好，横槊小留连。"]},{"t":"送杜阳安奉亲还蜀 其一","f":"五言律诗","c":["访落方勤止，而翁苦掉头。","立几遗世独，行盍为王留。","日月驰双毂，乾坤寄一舟。","勿缘归计得，忘却纬边忧。"]},{"t":"送徐显道尉无锡","f":"五言律诗","c":["握手不禁别，庭梧声欲秋。","云霄生脚底，田里付眉头。","敬是禔身柱，和为应物舟。","卷旗蒲柳市，茶鼎雨飕飕。"]},{"t":"送秦秘监还蜀 其二","f":"五言律诗","c":["蜀产班行几，分符又去之。","气完吞落日，心定发凉飔。","蝇虎攫何壮，蜗牛升更痴。","见几能许早，别思渺江蓠。"]},{"t":"送秦秘监还蜀 其一","f":"五言律诗","c":["岷峨人物古，淮海姓名香。","识面岁华晚，论心春昼长。","有怀胡去国，无愧好还乡。","呼酒犒三老，柁楼天正凉。"]},{"t":"送高才卿守永康 其二","f":"七言律诗","c":["岷峨悽怆未全苏，急要诸公着力扶。","政似刈葵难放手，民如种树莫搔肤。","雪山西去三边静，沬水东来万井腴。","小队还家聊上冢，天寒早与问无襦。"]},{"t":"送高才卿守永康 其一","f":"七言律诗","c":["同社纷纷早上坡，一麾独爱晚婆娑。","矜春桃李好能几，饱雨稻粱收更多。","管摄三才还正大，陶镕万象是中和。","西风未用轻分手，尚欲从君细切磋。"]},{"t":"送章君范之湖南幕","f":"五言律诗","c":["天阔孔鸾起，江晴荃若春。","亲荣知有子，主胜信宜宾。","岳麓盛古学，衡山多秀民。","平生金玉质，更看濯磨新。"]},{"t":"送程于潜 其一","f":"五言律诗","c":["溪山民物古，政理器能宽。","平易见眉睫，明清生肺肝。","春风帘影暖，霜月研声寒。","野老自相语，元丰崔长官。"]},{"t":"送程于潜 其二","f":"五言律诗","c":["溯紫催飞舄，攒红簇去鞍。","吾邦倾市送，旁邑塞涂看。","清庙登牺象，明庭峙孔鸾。","野翁麋鹿友，时与讯平安。"]},{"t":"送程宗武游岝崿","f":"五言律诗","c":["骤暖揠芳意，薄游烘软尘。","乱山云气晓，啼鸟杏花春。","人物少催老，物华新换陈。","一声铿尔瑟，沂水绿鳞鳞。"]},{"t":"送澄维那访旧湖山","f":"五言律诗","c":["梅子酸犹浅，桃花艳已饶。","春风开口吸，明月换肩挑。","鹤向平湖放，猿从古洞招。","出门天地阔，何处不逍遥。"]},{"t":"送黎德升出守眉州 其二","f":"五言律诗","c":["同是郾城客，对床如弟兄。","秋风双鬓改，落日寸心明。","终古方书在，随时局面更。","公馀经济学，讲贯不嫌精。"]},{"t":"送黎德升出守眉州 其一","f":"五言律诗","c":["霜隼健毛骨，冥鸿高羽翰。","来迟怀去速，退易挽留难。","文物声明郡，中和孝友官。","大冯棠荫在，多放一分宽。"]},{"t":"重过剑门","f":"五言律诗","c":["众水东瞿峡，连山北剑门。","地非甘习坎，天欲护全坤。","直上云千尺，中间月一痕。","客怀无柰恶，索酒自招魂。"]},{"t":"钟云叔挽诗","f":"五言律诗","c":["秋隼风神耸，春云笔势奇。","人情方共属，天理竟难窥。","哭子零丁母，啼耶娅姹儿。","落花飞絮急，行道亦伤悲。"]},{"t":"钟太君挽诗","f":"五言律诗","c":["护额锦裁帕，扶腰珠络衣。","几回呼使进，尽日醉言归。","径古梅成荫，堂深桂合围。","重来无复拜，春色黯斜晖。"]},{"t":"钟惠叔转示赵临安两山堂诸公诗刻随喜二首 其二","f":"五言律诗","c":["朵颐常逐逐，观复自休休。","静昼青竹笋，深春黄栗留。","觉圆熏穟直，梦破茗华浮。","为问连山易，床头好在不。"]},{"t":"钟惠叔转示赵临安两山堂诸公诗刻随喜二首 其一","f":"五言律诗","c":["两峰高峙玉，五亩秀含滋。","细柳未眠种，脩篁方醉移。","雨将云出谷，水引月归池。","动静天机密，何人共一卮。"]},{"t":"闻山阳夏全之变","f":"七言律诗","c":["洮湟私牍旧开边，淮楚依然样子传。","抱虎寝蛟心不保，护疽讳蛊祸相挻。","河流三舍尽人血，城阖四门无灶烟。","昨夜洗兵盈尺雪，华夷齐贺太平年。"]},{"t":"除妄","f":"五言律诗","c":["酒泉能醉么，饭颗免饥不。","万事得如愿，一生应莫愁。","凉风高放鹤，落日倒骑牛。","诸妄冰消尽，吾师马少游。"]},{"t":"新年","f":"五言律诗","c":["欲识新年课，都非旧日图。","词分诗料帐，酒夺饭工夫。","锻息柳边手，镊闲花里须。","寒消芳草绿，打急办行厨。"]},{"t":"除夜哭内","f":"七言律诗","c":["密雪疏风客屋穿，几回除夕伴忧煎。","团栾方索日边饭，契阔已成松底眠。","画火何堪思旧事，理衣谁与管新年。","平时戒汝无多酌，争得屠苏到汝前。"]},{"t":"奚左藏挽诗二首 其二","f":"五言律诗","c":["诸老定交早，群儿惊见稀。","功名身韫椟，翰墨世传衣。","龟寿前占梦，鸥盟晚息机。","吴头耆旧尽，搔首送斜晖。"]},{"t":"奚左藏挽诗二首 其一","f":"五言律诗","c":["理学不远复，躬行毋自欺。","志虽千万往，材仅二三施。","花竹觥筹密，云山步屐迟。","眇然人物里，公竟止于斯。"]},{"t":"奚知县挽诗","f":"五言律诗","c":["敏锐霹雳手，宽平云梦胸。","雄台高幕画，剧邑富民庸。","帆挂风方駃，戈挥日又舂。","炊粱剪春韭，无复奉从容。"]},{"t":"恭和御制赐吴叔告已下闻喜宴诗","f":"七言律诗","c":["致主唐虞泽兆民，贤才端是国精神。","作人欲返皇风古，拔士先随圣化新。","收敛文章归献替，安排事业到弥纶。","宸章属望丁宁甚，上答天恩莫爱身。"]},{"t":"挽万登仕","f":"五言律诗","c":["种德谏议窦，处心承事黄。","池园花竹老，庭户简编香。","四世环叠綵，百年酣累觞。","紫微身不到，丹墨付诸郎。"]},{"t":"挽中书俞侍郎 其二","f":"五言律诗","c":["铨省承新渥，词垣访旧阴。","颓波回万折，断岸立千寻。","祇谓人犹己，那思昔异今。","时清犹愤死，天地是知心。"]},{"t":"挽中书俞侍郎 其一","f":"五言律诗","c":["器重千钧鼎，胸涵万斛舟。","文章欧六一，政事富青州。","偃月知谁在，灵光独我留。","貂蝉虽未着，不作汗青羞。"]},{"t":"挽元寂王道士","f":"五言律诗","c":["盘隐早具眼，栗斋仍点头。","丰碑俱好在，烂醉更何求。","院静桃开落，林深鹤去留。","翛然风露表，无处觅青牛。"]},{"t":"挽礼上人","f":"五言律诗","c":["盘屈虹蜺气，空山老白云。","酒因陶令买，芋为邺侯分。","甘露门知味，毗耶藏著勋。","南轩无复见，岩卉自清芬。"]},{"t":"挽孙谦伯 其二","f":"五言律诗","c":["日月无多子，乡邦失两贤。","直为吾党恸，不作世情怜。","握手春风醉，论心夜雨眠。","耳言犹历历，何忍表君阡。"]},{"t":"挽孙谦伯 其一","f":"五言律诗","c":["文妙生花笔，名成映雪书。","处家贫似富，应物密如疏。","荐墨交黄绶，荣光照板舆。","出门车折轴，天理竟何如。"]},{"t":"挽阮开之","f":"五言律诗","c":["穷达皆归命，亏成不挂心。","醉馀便腹睡，棋罢掉头吟。","孔雀门阑旧，骊驹院落深。","可堪重剥啄，寂寂杏花阴。"]},{"t":"挽阮宣义","f":"五言律诗","c":["夜气精神饱，春风笑语酣。","脩篁森道北，丛桂郁城南。","雨露荣三釜，烟云老一龛。","泷冈阡上路，秋思薄晴岚。"]},{"t":"挽阮倅","f":"五言律诗","c":["胶庠推博洽，州县著廉平。","人物万夫特，山川千古英。","虬髯横意气，猿臂郁功名。","一掬同年泪，西风浩荡情。"]},{"t":"挽伯父 其一","f":"五言律诗","c":["白发儿随母，苍颜弟对兄。","四休元易足，一笑更何营。","论事丝弦直，存心镜面平。","德人今已矣，谁与嗣乡评。"]},{"t":"挽李丞","f":"五言律诗","c":["笃敬古君子，公平贤大夫。","笔端知已有，券外得心无。","落日摇墙竹，凄风堕井梧。","蓄深施不尽，留与读书符。"]},{"t":"挽李贯之郎中 其二","f":"五言律诗","c":["天定何能待，西风杳去槎。","斯人嗟已矣，吾道信非耶。","石泐名犹在，江空恨更赊。","濂溪应配食，杯水荐寒花。"]},{"t":"挽李贯之郎中 其一","f":"五言律诗","c":["刚大平生气，诚明问学功。","不为官所饵，宁以道而穷。","论事冯唐力，忧时贾谊忠。","朝阳无此凤，何止哭江东。"]},{"t":"挽李漕 其二","f":"五言律诗","c":["百折溪山里，佳哉有此翁。","名方随政起，命已坐文穷。","满眼棠阴在，回头橘隐空。","诗髯无复磔，万象自春风。"]},{"t":"挽李漕 其一","f":"五言律诗","c":["翰墨多推毂，功名早着鞭。","风行青草外，春到白盐边。","老去心犹壮，归来意正便。","如何天不慭，烟雨閟新阡。"]},{"t":"挽俞致政","f":"五言律诗","c":["涉世万缘薄，爱书双眼明。","身从平处立，道向拙中生。","啖蔗何妨晚，栽槐恰待荣。","偈成投笔去，天阔暮云横。"]},{"t":"挽俞景梁","f":"五言律诗","c":["亿计桥门士，输君第一筹。","文为天下样，行与古人谋。","磨铁素心在，注金苍鬓休。","梅边清绝梦，谁更酒扶头。"]},{"t":"挽钟孺人","f":"五言律诗","c":["夫没姑嫜老，年芳鉴珥新。","孤峰晴后雪，硕果剥中春。","命义生无愧，言容死未陈。","西风吹拱木，双剑合龙津。"]},{"t":"挽章冠叟","f":"五言律诗","c":["卷却青云靶，书来意转平。","于斯观所养，知不失其亨。","梧竹自师友，梅矾皆弟兄。","悲风吹梦远，不朽是乡评。"]},{"t":"挽铜里叶提点","f":"五言律诗","c":["养性居士白，用心承事黄。","春风花竹墅，秋雨鲙莼乡。","简淡趋真谛，廉平絜义方。","志幽无长语，手墨粲琳琅。"]},{"t":"桂子次韵赠阮甥","f":"七言律诗","c":["一树青青桂子荣，广寒宫殿玉为楹。","不知天上何年堕，故使人间有种生。","风影碎摇签帙爽，露华倒洗笔头清。","寸田更与加培埴，收取天香染姓名。"]},{"t":"浮溪周居士挽诗","f":"五言律诗","c":["野水岗头屋，春风竹里厨。","所安仁者静，其乐道之腴。","遗逸盍徵诏，耆英空画图。","诗书根气远，丛桂蔚相扶。"]},{"t":"烛下次海棠","f":"七言律诗","c":["红深翠浅浣花春，投老相逢过所欣。","有许精神宜半睡，无多酝藉莫全醺。","涵渟芳露须饶月，笼护晴晖不碍云。","成就化工真富贵，天香更与牡丹分。"]},{"t":"病目","f":"五言律诗","c":["日过学不力，年催名未芳。","心期虽皦皦，目视已茫茫。","灯叠青红晕，书纷黑白行。","蒲团深瞑坐，禅味觉偏长。"]},{"t":"被檄出城","f":"词","c":["引却东风觱栗声，竹舆如斗作春行。","山中祗怪天能窄，栈外方知地本平。","黔袂炼?斜屋小，黄缨淘矿乱砂明。","终年一饱难如许，愧尔炉熏管送迎。"]},{"t":"读书楼 其二","f":"七言律诗","c":["引却蜂衙一事无，求师尚友圣贤俱。","激昂意气中兴颂，收敛身心太极图。","畬火明边饥虎过，渡船声外老鸧呼。","江南云水宽多少，万里深山着此臞。"]},{"t":"读书楼 其一","f":"七言律诗","c":["流水青山一榻深，铜柯石干半窗阴。","公馀点校七分易，老去服行三字箴。","消长乘除观物理，存亡操舍验人心。","日长大得官闲力，乳燕鸣鸠尽好音。"]},{"t":"读书蠖室","f":"五言律诗","c":["扁为孜禅作，侵寻二十年。","屈伸聊复尔，俛仰故依然。","直榻无馀地，横窗不欠天。","焚香长诵罢，风雨响山川。"]},{"t":"读汉事","f":"五言律诗","c":["病禹逢沈骜，酣参事懦盈。","阴阳眠燮理，天地醉财成。","河岳瞢腾立，羲娥蹩躠行。","无人能唤醒，作意造升平。"]},{"t":"钱德成山水窟","f":"五言律诗","c":["亦有黄金埒，非无瑞锦窠。","养蒙知趣早，观复用功多。","嘉客贲场谷，硕人槃涧阿。","时平风日好，花竹几行窝。"]},{"t":"高壶隐挽诗","f":"五言律诗","c":["种德黄芽鼎，陶心碧玉壶。","多交天下士，几唤竹间厨。","秋雨凉催读，春风醉索扶。","忽成观化去，冷落辋川图。"]},{"t":"高斋","f":"五言律诗","c":["江浒行厨转，关头细路过。","手摩如象石，目送卧龙坡。","肮脏云端柏，鬅鬙雨后莎。","晚来晴更好，舟发乱山阿。"]},{"t":"婆饼焦","f":"七言律诗","c":["万斛精神一握身，清吭宛转欲飞尘。","鸡才唱后便知晓，燕未来前先得春。","惊觉海棠休苦睡，提醒杨柳莫空颦。","最怜吉语能相报，麦熟同为鼓腹人。"]},{"t":"宿柁头次及甫入沌韵","f":"七言律诗","c":["手遮西日望褒斜，百折舟行尚玉沙。","风趁港回帆落柱，草迷路断牵收车。","长烟漠漠非吾土，老树离离似我家。","今夜宿头应更好，月明四面尽芦花。"]},{"t":"寄崔帅卿","f":"七言律诗","c":["归鸿只影宿汀洲，梦绕芦花不柰愁。","颍谷杯羹无日遗，翳桑橐饭有时酬。","功名旷世来斯受，议论惊人合则留。","此事大关天下望，殷勤为报古扬州。"]},{"t":"寄题永嘉林氏真意堂","f":"五言律诗","c":["萱草径庭寂，橘花窗户明。","我惟天地性，物自古今情。","玄酒无穷味，朱弦不尽声。","道从涵泳得，宽作读书程。"]},{"t":"寄题辛氏尘外楼","f":"五言律诗","c":["罗浮三十里，楼对玉崔嵬。","风卷软红去，云扶飞翠来。","会心须尽帙，适性莫多杯。","除得翳根尽，灵光生镜台。"]},{"t":"寄题真相寺遥月堂仍简礼上人","f":"五言律诗","c":["四特递盈阙，八还齐闇明。","须从心观觅，莫认指摽生。","地僻人声远，山空夜气清。","何时煨芋火，相与听瓶笙。"]},{"t":"崔绵谷共赋亭次韵","f":"五言律诗","c":["风度崔秋浦，声名郑子真。","为便官事少，不厌客来频。","竹里觥筹密，花边屐齿新。","拍栏谁得句，唤起主林神。"]},{"t":"族叔畴甫老死于场屋人共惜之其子得瑞梅于园实三而花一花十二瓣碧色其遗文发祥欤老人为赋诗敬用韵","f":"七言律诗","c":["乃翁抱璞售无媒，去作修文地下魁。","换骨法从青子得，返魂香自绿阴来。","诗书根气春无尽，清白源流庆有开。","十二循环花瓣异，信知天理有时回。"]},{"t":"晚莲","f":"七言律诗","c":["飒然秋入井梧嘶，窗下红蕖始脱泥。","但有意开何论晚，纵无力上不嫌低。","鱼贪芳影机还熟，蝶怕深香路自迷。","更把闲情坚耐着，明年花与屋檐齐。"]},{"t":"晨起","f":"五言律诗","c":["入夜风收雨，迟明暖酿霜。","人穷髭易白，地瘦叶先黄。","绣眼语丛竹，画眉啼断岗。","炊烟犹未动，吾亦起歌商。"]},{"t":"棕榈","f":"五言律诗","c":["旧脱败蓑乱，新添华节高。","肃容春尚静，侠气夏方豪。","黄孕子鱼腹，青披孔雀尻。","丰撞知可制，雷动景钟号。"]},{"t":"渚宫","f":"五言律诗","c":["孤城铜斗匝，枉渚玉环连。","柳老虫穿蚀，花残蝶扑缘。","功名棋腹角，势利蜜中边。","落日兴亡里，谁同药玉船。"]},{"t":"移居西郭重楼","f":"七言律诗","c":["欲归未办买山资，东寄西存漫一枝。","楼上起楼渠自巧，客中作客我何痴。","崎岖溪步通虚市，郁屈山蹊护短篱。","不用子猷亲种竹，屋头元有绿猗猗。"]},{"t":"章升伯妻孺人挽诗","f":"五言律诗","c":["婉娈从君子，青云远大谋。","乐羊灯火夜，李侃鼓鼙秋。","露舄凫迎喜，星机鹊送愁。","诰花纷五色，光动九原头。"]},{"t":"雪留董景扬","f":"七言律诗","c":["一色凝云合大和，定知宜瑞不宜多。","饥餐乌昧世皆是，饱进羊羔人几何。","抢地折腰纷岸筱，撑天强项独庭柯。","留君待放晴光出，同步春风十二窝。"]},{"t":"帽子檐水宿","f":"五言律诗","c":["聚石桩长缆，依沙插短舻。","日昏山虎下，风急水鸧呼。","道岂随时变，人须出力扶。","仲由儿女见，谓欲果乘桴。"]},{"t":"敬次老人即事","f":"七言律诗","c":["韶华九十恰平分，过化中存一点神。","草脱烧痕非故色，梅收花事又新人。","正襟危坐三灵会，拥鼻长谣万象宾。","酬答风光惟办此，可能春梦到天津。"]},{"t":"敬和老人石菖蒲","f":"七言律诗","c":["西风摆脱络头丝，荪壁为家不问蓍。","分得九华烟雨壑，种将五老水云芝。","戟髯洒洒精神健，剑脊棱棱气骨奇。","窗外几多凡草木，为谁张王为谁衰。"]},{"t":"敬和老人青梅","f":"七言律诗","c":["雪水迎风细作鳞，青青又是故园春。","只知和鼎非凡子，岂料升盘有苦人。","还我核来机转熟，寄渠花去意犹新。","侧生底事摇车颊，空作渔阳一点颦。"]},{"t":"敬和老人盆池","f":"七言律诗","c":["埋盆作沼野人家，数斛山泉拍两涯。","人立晚风凉似水，荷浮香气胜于花。","蛙声恰恰宜飞雨，鹜影依依欠落霞。","齐物逍遥无大小，不须烦恼发生丫。"]},{"t":"敬和老人览镜","f":"七言律诗","c":["西谷柴车手自巾，风吹不到庾郎尘。","回光返照千江月，复命归根一点春。","永昼同窗陶处士，凉宵专席竹夫人。","徐公好丑浑休问，认取青铜镜里真。"]},{"t":"敬和老人荷花","f":"七言律诗","c":["红红白白两般栽，浅浅深深一气催。","但爱透从清水出，不辞脱自淤泥来。","随花着盖相依立，聚菂为房忍擘开。","妙洁色香无间断，床头更拨洗儿醅。"]},{"t":"敬和老人寓舍","f":"五言律诗","c":["邹不辞三徙，滕何爱一廛。","典衣宽酒债，乞米续炊烟。","胜败供飞雹，亏成付响泉。","东山时撰屦，花底弄潺湲。"]},{"t":"暑夕","f":"五言律诗","c":["楼高收晚照，野迥送宵阴。","鹭下汀沙静，萤行岸竹深。","撄宁和顺气，缘督正平心。","转物天机妙，昭文不在琴。"]},{"t":"畴甫叔挽诗 其二","f":"五言律诗","c":["撰屦西山路，寻春得重陪。","那知分手去，不作转头来。","寂寂双溪雪，依依半树梅。","经行陈迹在，横涕湿苍苔。"]},{"t":"畴甫叔挽诗 其一","f":"五言律诗","c":["南渡几年里，深山谁力书。","独君酣百战，许我丐三馀。","参斗明灯烬，湖江渴砚蜍。","斯人犹不第，天理竟何如。"]},{"t":"答及甫见和 其二","f":"五言律诗","c":["我爱湖南客，从横正复奇。","短裳甘制芰，破釜懒燃萁。","愤世惟堪饮，忧边不到诗。","最怜孤寂甚，欲为唤罗龟。"]},{"t":"答及甫见和 其一","f":"五言律诗","c":["唤晴山鸟滑，辟暑水花明。","蜀隶绵犹重，吴侬葛自轻。","交情潘接魏，师法尹从程。","鹅鸭堪供客，多烦拗项烹。"]},{"t":"答子有","f":"七言律诗","c":["高吟梁甫卧隆中，眼底驽骀不足空。","清白自将千古月，温凉不定六时风。","交梨火枣根苗长，翠竹黄花信息通。","楼外秋莺强饶舌，笑人迟却黑头公。"]},{"t":"答王仲钧 其二","f":"五言律诗","c":["老镜风霜饱，离觞岁月悠。","曲多传郢水，诗亦到苏州。","拽转撩天鼻，抽将闹市头。","投林毋用急，时至会封侯。"]},{"t":"答骆肖秦","f":"五言律诗","c":["过我葵榴巷，留君笋薤厨。","襟怀新雨快，面目故山癯。","自笑孤飞鹤，谁怜返哺乌。","未应埋没得，囊有万骊珠。"]},{"t":"答隆庆李守","f":"五言律诗","c":["万里一天碧，百怀双鬓秋。","凄其占后会，展也企前脩。","风露昂藏鹤，烟波浩荡鸥。","书来如觌面，香满藕花洲。"]},{"t":"答程及甫徐少望","f":"七言律诗","c":["客程欠舞綵衣斑，懒把茱萸对酒看。","凉思着人穷脚健，丰年到手老怀宽。","有风不怕江流逆，无愧何忧蜀道难。","但愿浣花花好在，免教杜曲眼长寒。"]},{"t":"答赠刘交代 其二","f":"五言律诗","c":["番上松扶塞，逢迎桔柏埼。","高风挹元祐，遗事说开禧。","丹凤岗头咮，苍龙洞口漦。","秋光无限好，管勾费新诗。"]},{"t":"答赠刘交代 其一","f":"五言律诗","c":["危栈摩千仞，牢关护一窝。","山巅闲地少，溪面白云多。","昼永琴书乐，年丰鼓角和。","官清谁得似，祗欠客经过。"]},{"t":"落枣","f":"五言律诗","c":["杨柳天机浅，樱桃世态深。","空山鸠问答，肥水鹜浮沉。","格物知穷理，观时会省心。","最怜谁氏女，沙里日淘金。"]},{"t":"新井道间","f":"五言律诗","c":["饮涧思浮白，行山当踏青。","柏边桤叶长，麦里豆花零。","清哢愁肠泮，疏香倦眼醒。","牛头应不远，三舍即盐亭。"]},{"t":"新秋药名 其二","f":"七言律诗","c":["两眼旋花雪点须，钻头故纸枉工夫。","倦怀懒附子公椟，闲性熟谙摩诘图。","枝拂云香行到桂，叶随风舞又催梧。","乘槎欲到空青问，织女牵牛事有无。"]},{"t":"新秋药名 其一","f":"七言律诗","c":["老色苍苍耳向聋，秋声欺得白头翁。","已甘草诏元无分，只苦耽诗久欠功。","引兴从容风月足，放怀浪宕水云空。","雨馀凉意生庭户，夜半天河鹊信通。"]},{"t":"毁邓艾庙","f":"五言律诗","c":["蜀庸无与守，魏吃浪成名。","血已洿砧机，魂犹饕酒牲。","柏溪融雪泻，玉案倚云横。","潴薙莫留迹，山川方气平。"]},{"t":"解缆","f":"五言律诗","c":["春落平芜外，舟行白雨边。","鸠应山尔汝，橹画水之玄。","官冷谁能吏，身闲便是仙。","康庐真个去，信有夙生缘。"]},{"t":"谨次老人至节韵","f":"七言律诗","c":["但见阴阳递斡流，谁知阳本未尝休。","善端继继无穷脉，元化生生不尽头。","杜牧浪将箱劝读，少陵空为线添愁。","何如静坐观其复，一点灵台造物游。"]},{"t":"谨和大人喜晴","f":"七言律诗","c":["雨脚如麻日日然，垂成生恐坏丰年。","九重肸蚃通方寸，一点光明遍大千。","喜动朝行花底散，愁销野次苇间缘。","奄观铚艾霜风晚，重压牛车倍费鞭。"]},{"t":"谨和老人九日","f":"七言律诗","c":["楼头独立夕阳西，摇落高风万木嘶。","人自官刍衔马口，我方社酒荐豚蹄。","一尘不著青铜镜，万法皆空黑漆篦。","节后龙山应更好，秋光拍满锦障泥。"]},{"t":"谨和老人古砚韵","f":"五言律诗","c":["破坏憨僧衲，凹攲漫叟洼。","吐云头缩蜃，啖月口呿蟆。","宫㜮愁难捧，堂胥怒可挝。","莫贪濡笔利，浪草侍中麻。"]},{"t":"谨和老人初冬即事","f":"七言律诗","c":["莫怒狙公赋芧悭，万缘一定不容干。","老便窗下迷离暖，醉爱尊前郭索寒。","屑玉晨光明沆瀣，流珠夜气郁兰玕。","但能饱吃长年饭，射虎南山有分看。"]},{"t":"谨和老人明朝中春 其二","f":"七言律诗","c":["淡黄深碧上春衫，无限春怀岂易谭。","随手去来拈放一，到头得失暮朝三。","日烘花气通玄牝，雨洗山光涨蔚蓝。","熟听五更晴哢好，不须多恨罢朝参。"]},{"t":"谨和老人明朝中春 其一","f":"七言律诗","c":["田夫野老布长衫，郊外相逢与共谭。","一把年华将望六，九分春色又过三。","竹鸡绝叫茶生笋，梅子微酸酒熟蓝。","流转风光无间断，此身元与化功参。"]},{"t":"谨和老人罗山","f":"五言律诗","c":["自铸铁成错，谁吹灰使然。","俗情床上下，野趣蜜中边。","花艳明光锦，苔痕白打钱。","醉翁诗板在，山莫放童颠。"]},{"t":"谨和老人春行","f":"七言律诗","c":["抗疏明时效伏伽，一归七度试春纱。","柔风绿遍庭前草，细雨红催陌上花。","惠远买来犹浊酒，赵州吃去只粗茶。","回头恰恰莺啼处，黄四娘今尚有家。"]},{"t":"谨和老人夏日东山即事 其二","f":"五言律诗","c":["菜把野园送，花枝邻巷赊。","捣蟾和绛雪，骑斗弄青霞。","古帖临禽李，新诗续稻瓜。","晚凉随杖履，携酒访鱼槎。"]},{"t":"谨和老人夏日东山即事 其一","f":"五言律诗","c":["刬草根须尽，传花叶未多。","明波撑窣堵，老石卧盘陀。","煨美甘分芋，蒸肥欠裹荷。","醒然下山去，明月满林阿。"]},{"t":"谨和老人欲还故庐","f":"七言律诗","c":["飕飕破屋小青裯，客枕频年寄道周。","行止非人真可笑，穷通有命尚何愁。","春风旧垒双飞燕，宿雨新巢百拙鸠。","信是还家贫亦好，德人何处不天游。"]},{"t":"谨和老人雪晴","f":"七言律诗","c":["云屏九折跨三休，公欲行春雪不愁。","逗暖流澌鸣暗谷，送晴倒景漾层楼。","似无似有草痕动，半落半开花气浮。","婆饼焦声林外起，便从野渡唤横舟。"]},{"t":"谨和老人惠山泉 其二","f":"五言律诗","c":["第二水泉动，斜三封印通。","爱奇亲煮雪，得隽细生风。","酒肺苏将渴，诗情洗尽穷。","娉婷须好买，供奉读书公。"]},{"t":"谨和老人惠山泉 其一","f":"五言律诗","c":["取水驿符到，喊山旗信通。","碾分花底月，炉受竹间风。","金谷正觅醉，玉川谁道穷。","顶门甘露入，唤醒主人公。"]},{"t":"谨和老人赋牛尾狸 其二","f":"五言律诗","c":["北雪佛狸种，西风金狗秋。","谋生贪过鼠，逃死喘如牛。","糟熟涎奴舌，齑芳点客头。","何时明猎火，吞尽楚青丘。"]},{"t":"谨和老人赋牛尾狸 其一","f":"词","c":["踏白霜明夜，牵黄木叶秋。","斓斑文未豹，觳?炙先牛。","压玉开三面，蒸酥让一头。","酒边纤手削，醉倒老浮丘。"]},{"t":"谨和老人赋退朝","f":"五言律诗","c":["世事鹏斥鴳，人情燕伯劳。","心须腔放阔，眼要孔提高。","陈力惟求健，承恩敢恃牢。","熟思归计是，春酒荐蒌蒿。"]},{"t":"谨和老人赋梅","f":"七言律诗","c":["寄得江南驿信来，窥林映水几枝开。","形容绮语空能絮，酬答芳心总已灰。","厌旧趋新和粉染，夺真弄假点酥裁。","纷纷儿女春风恼，却笑诗翁醉打隈。"]},{"t":"谨和老人瘳字韵","f":"七言律诗","c":["本期洗眼看伊周，到此华胥只梦游。","烂熳苍苔心事晚，婆娑红槿鬓华秋。","藏头欲效钻沙鳖，扪舌空成噍草牛。","饭豆芋魁浑好在，得归不药病还瘳。"]},{"t":"酬吴教程丞","f":"七言律诗","c":["六花结阵护轻寒，缓带西风夹谷坛。","破竹正期多算胜，把萸何暇半酣看。","声驱黑祲千山卷，气摄黄河一夜乾。","识得天津裴度面，人心已作太山安。"]},{"t":"蜘蛛","f":"七言律诗","c":["已迫斜阳欲坠时，谋身只怕脚行迟。","纵横笼罩大为网，首尾经纶浑是丝。","腹饱飞虫肥似瓠，喙工毒螫利于锥。","朝来猛被儿童扫，不放檐牙一点遗。"]},{"t":"赠希声居士","f":"五言律诗","c":["汗漫骑鲸去，西风发半簪。","安心元是药，得趣不妨琴。","人静蛩鸣夜，天寒月出林。","为君重洗耳，别酒不须斟。"]},{"t":"赠俞次孟","f":"词","c":["古屋无过客，新凉得可人。","为回黄觳?，同饭紫轮囷。","社雨初华稻，秋风未老蘋。","扁舟苕霅去，诗料正横陈。"]}]};